INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem:-land-of-the-babes', 'Playstation', 'Duke Nukem: Land of the Babes', '2000', 'Shooter', 'Nerve Software', '2', 'Third-person shooter', 'Third-person shooter with an emphasis on action and humor.', 'Rescue the "babes" and stop an alien threat in a post-apocalyptic world.', 'An explosive action game starring the king of one-liners.', 'Duke Nukem: Land of the Babes delivers classic Duke attitude. Use a massive arsenal to blast aliens and save the world in this high-octane shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem:-time-to-kill', 'Playstation', 'Duke Nukem: Time to Kill', '1998', 'Action', 'Nerve Software', '2', 'Third-person shooter', 'Third-person action-adventure with time-traveling themes.', 'Travel through different historical eras to eliminate alien invaders.', 'A "Tomb Raider" style adventure featuring Duke''s signature style.', 'Duke Nukem: Time to Kill takes the fight to the past. Battle through Ancient Rome and the Wild West in this challenging and witty action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('duke-nukem:-total-meltdown', 'Playstation', 'Duke Nukem: Total Meltdown', '1995', 'Shooter', 'id Software', '2', 'First-person shooter', 'First-person shooter featuring the classic PC levels and new content.', 'Blast through Los Angeles and space to stop the alien invasion.', 'The definitive PS1 port of the legendary Duke Nukem 3D.', 'Duke Nukem: Total Meltdown brings the ultimate FPS experience home. Includes an exclusive fourth episode and a rock-heavy soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dune-2000', 'Playstation', 'Dune 2000', '1998', 'Strategy', 'Westwood Studios', '2', 'Real-time strategy', 'Real-time strategy based on the classic Frank Herbert novel.', 'Command the Atreides, Ordos, or Harkonnen to control the spice.', 'A polished console remake of the game that defined the RTS genre.', 'Dune 2000 offers deep strategy and cinematic FMV. Manage your base and survive the desert worms in the battle for Arrakis.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('dynasty-warriors', 'Playstation', 'Dynasty Warriors', '1997', 'Action', 'Omega Force', '2', 'Hack and slash', '3D weapon-based fighting game with a historical Chinese theme.', 'Defeat rivals in one-on-one combat to claim the ultimate power.', 'The first entry in the series before it became a "Musou" brawler.', 'Dynasty Warriors for PS1 is a technical 3D fighter. Master the blade and use precise timing to defeat legendary warriors of the Three Kingdoms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('et-the-extra-terrestrial---interplanetary-mission', 'Playstation', 'E.T. the Extra-Terrestrial - Interplanetary Mission', '2002', 'Platformer', 'Digital Eclipse', '1', '2D platformer', '3D action-adventure featuring space exploration and puzzles.', 'Help E.T. collect parts for his interplanetary communicator.', 'A family-friendly adventure based on the beloved film universe.', 'E.T. the Extra-Terrestrial - Interplanetary Mission takes the friendly alien on a galactic quest. Solve puzzles and use special powers to return home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('earthworm-jim-2', 'Playstation', 'Earthworm Jim 2', '1996', 'Platformer', 'Shiny Entertainment', '1', '2D platformer', 'Surreal 2D side-scrolling platformer with wacky humor.', 'Rescue your friend Peter Puppy and defeat Psy-Crow.', 'A visually stunning sequel with creative and bizarre level design.', 'Earthworm Jim 2 brings the "groovy" hero back for more madness. Use new suits and weapons in this masterpiece of 2D animation and comedy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('easter-bunnys-big-day', 'Playstation', 'Easter Bunny''s Big Day', '2000', 'Educational', 'Bay Area Multimedia', '1', 'Educational adventure', 'Collection of mini-games and puzzles with a holiday theme.', 'Help the Easter Bunny prepare for the big day by completing tasks.', 'A simple and charming game designed for younger children.', 'Easter Bunny''s Big Day offers lighthearted fun for kids. Enjoy various Easter-themed activities and puzzles in this cheerful family title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('echo-night', 'Playstation', 'Echo Night', '1998', 'Horror', 'FromSoftware', '1', 'Psychological horror', 'First-person psychological horror adventure with a focus on spirits.', 'Explore an abandoned ship and use a magical stone to save souls.', 'A haunting and atmospheric cult classic from FromSoftware.', 'Echo Night delivers a unique, non-combat horror experience. Solve the mysteries of the departed and change the past in this chilling adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('echo-night-2:-lord-of-nightmares', 'Playstation', 'Echo Night 2: Lord of Nightmares', '1999', 'Horror', 'FromSoftware', '1', 'Psychological horror', 'First-person psychological horror set in a haunted mansion.', 'Discover the secret of the "Lord of Nightmares" to find your father.', 'A deep and eerie sequel that expands on the original''s spirit mechanics.', 'Echo Night 2: Lord of Nightmares offers multiple endings and a thick atmosphere. Navigate a world of ghosts and shadows in this rare horror gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecw-anarchy-rulz', 'Playstation', 'ECW Anarchy Rulz', '1999', 'Sports', 'Acclaim Studios Austin', '4', 'Pro wrestling', '3D professional wrestling with an "extreme" hardcore focus.', 'Win championships using weapons and brutal wrestling moves.', 'The final ECW title on PS1 featuring a massive roster and modes.', 'ECW Anarchy Rulz brings the violence of the bingo hall home. Use tables, chairs, and barbed wire to dominate your opponents in this gritty fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ecw-hardcore-revolution', 'Playstation', 'ECW Hardcore Revolution', '2000', 'Sports', 'Acclaim Studios Salt Lake City', '4', 'Pro wrestling', '3D professional wrestling with an emphasis on hardcore rules.', 'Climb the ranks of the ECW and win the World Heavyweight Title.', 'A fast-paced wrestling game featuring the stars of the extreme era.', 'ECW Hardcore Revolution delivers the "Hardcore" experience. Featuring blood, weapons, and high-flying moves, it captures the essence of the promotion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ehrgeiz:-god-bless-the-ring', 'Playstation', 'Ehrgeiz: God Bless The Ring', '1998', 'Fighting', 'DreamFactory', '2', '3D fighting', '3D fighting game featuring a deep quest mode and RPG elements.', 'Win the tournament to claim the ancient sword, Ehrgeiz.', 'A unique fighter featuring guest characters from Final Fantasy VII.', 'Ehrgeiz: God Bless The Ring offers 360-degree combat and a massive dungeon-crawling mode. Battle as Cloud or Sephiroth in this innovative crossover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('einhander', 'Playstation', 'Einhander', '1998', 'Shooter', 'Square', '1', 'Side-scrolling shooter', 'Cinematic side-scrolling shooter with a 3D aesthetic.', 'Blast through enemy forces to stop an imperial conquest.', 'A visually stunning "shmup" known for its mechanical design.', 'Einhander is a masterpiece of the genre from Square. Steal enemy weapons and master the tactical "Gunpod" system in this high-octane shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('elemental-gearbolt', 'Playstation', 'Elemental Gearbolt', '1998', 'Shooter', 'Raising Hell Software', '2', 'Light gun shooter', 'Light-gun shooter with a deep story and RPG elements.', 'Use magical weapons to defeat a corrupt empire and its generals.', 'A beautifully animated shooter that supports the Guncon.', 'Elemental Gearbolt offers a cinematic experience with anime cutscenes. Master the elemental magic and uncover a tragic story in this unique shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eliminator', 'Playstation', 'Eliminator', '1998', 'Racing', 'Magenta Software', '2', 'Arcade racing', 'High-speed futuristic combat racing with weaponized cars.', 'Destroy rivals and finish first across diverse 3D tracks.', 'A fast and aggressive racer with a sci-fi edge.', 'Eliminator puts you in control of high-tech war machines. Use missiles and speed boosts to clear the track in this intense arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('espn-x-games-pro-boarder', 'Playstation', 'ESPN X-Games Pro Boarder', '2001', 'Sports', 'Z-Axis', '2', 'Extreme sports', 'Extreme snowboarding simulation featuring professional riders.', 'Score massive points with tricks and win races to become pro.', 'An early and influential entry in the 3D snowboarding genre.', 'ESPN X-Games Pro Boarder brings the thrill of the mountain to PS1. Master the halfpipe and big air events in this high-energy sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('eternal-eyes', 'Playstation', 'Eternal Eyes', '2000', 'RPG', 'Sunsoft', '1', 'Tactical RPG', 'Tactical turn-based RPG with creature summoning mechanics.', 'Lead a group of heroes to stop the resurrection of a dark god.', 'A colorful strategy RPG with a focus on "Mappies" (puppets).', 'Eternal Eyes features deep tactical combat and unit customization. Evolve your magical creatures to create the ultimate army in this classic JRPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('europe-racer', 'Playstation', 'Europe Racer', '2000', 'Racing', 'Davilex', '2', 'Arcade racing', 'Arcade-style racing through famous European cities.', 'Win illegal street races across London, Paris, Berlin, and more.', 'A fast-paced racer focused on urban environments and speed.', 'Europe Racer takes the competition to the streets. Weave through traffic and outrun rivals in this vibrant and accessible arcade driving game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evil-dead---hail-to-the-king-usa', 'Playstation', 'Evil Dead - Hail to the King (USA)', '2000', 'Action', 'Heavy Iron Studios', '1', 'Action adventure', 'Third-person survival horror with hack-and-slash combat.', 'Survive the Necronomicon outbreak and save your girlfriend.', 'A gritty action-horror title based on the cult film franchise.', 'Evil Dead - Hail to the King features Bruce Campbell''s voice and dry wit. Use your chainsaw and boomstick to slice through Deadites in this dark adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('evil-zone', 'Playstation', 'Evil Zone', '1996', 'Adventure', 'Epoch', '1', 'Action adventure', 'Stylized 3D fighting game with a focus on story and cinematic moves.', 'Win the tournament to claim the power of the "Evil Zone."', 'A unique fighter with a TV-show style presentation and simple controls.', 'Evil Zone features a distinctive anime aesthetic and dramatic camera angles. Experience a character-driven story mode with easy-to-learn but hard-to-master combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('exhumed', 'Playstation', 'Exhumed', '1998', 'Adventure', 'Epoch', '1', 'Action adventure', 'First-person shooter set in ancient Egypt with Metroidvania elements.', 'Recover the artifacts of King Ramses to stop an alien invasion.', 'A legendary FPS known for its incredible lighting and exploration.', 'Exhumed (also known as Powerslave) is a masterpiece of the genre. Use mystical weapons and gain new abilities to navigate a trap-filled Egyptian world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('expendable', 'Playstation', 'Expendable', '2000', 'RPG', 'Epoch', '1', 'Dungeon crawler RPG', 'Top-down run-and-gun shooter with explosive arcade action.', 'Fight through hordes of enemies to save the last remnants of humanity.', 'A frantic, neon-soaked shooter with massive firepower and bosses.', 'Expendable offers non-stop shooting mayhem. Blast your way through alien-infested levels with a variety of high-tech weapons and power-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('expert', 'Playstation', 'Expert', '1995', 'Action', 'Technos Japan', '2', 'Side-scrolling beat ''em up', 'Board game simulation featuring various classic tabletop activities.', 'Outsmart opponents in traditional games like Chess and Backgammon.', 'A straightforward collection of classic and traditional board games.', 'Expert brings the digital tabletop to life. Enjoy polished versions of your favorite strategy and logic games in one convenient package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('explosive-racing', 'Playstation', 'Explosive Racing', '1999', 'Adventure', 'Index+', '1', 'Point-and-click adventure', 'Arcade-style racing with high-speed tracks and explosive power-ups.', 'Finish first while using traps and weapons to stop your rivals.', 'A chaotic racer where speed and destruction go hand in hand.', 'Explosive Racing delivers high-octane thrills. Navigate dangerous tracks and outrun the competition in this fast-paced, action-heavy driving game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-go-kart-racing', 'Playstation', 'Extreme Go-Kart Racing', '1999', 'Adventure', 'Index+', '1', 'Point-and-click adventure', 'Go-kart racing with 3D tracks and arcade physics.', 'Master the tight turns and win the seasonal karting championship.', 'A budget-friendly karting sim focused on pure racing mechanics.', 'Extreme Go-Kart Racing offers accessible fun for racing fans. Choose your driver and dominate the asphalt in this straightforward competitive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('extreme-pinball', 'Playstation', 'Extreme Pinball', '1997', 'Fighting', 'Tose', '2', '3D fighting', '2D pinball simulation with multiple themed tables.', 'Score maximum points by completing missions and hitting targets.', 'A fast-paced pinball game with aggressive table designs.', 'Extreme Pinball brings the arcade experience home with high-velocity gameplay. Tackle diverse tables and master the flippers to climb the high-score board.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('f1-world-grand-prix-usa', 'Playstation', 'F1 World Grand Prix (USA)', '1996', 'Fighting', 'BEC', '2', '2D fighting', 'Formula 1 racing simulation with licensed teams and drivers.', 'Win the FIA Formula One World Championship across global tracks.', 'A technical and realistic F1 racer for serious driving enthusiasts.', 'F1 World Grand Prix features authentic handling and weather effects. Experience the intensity of the 1997-1998 seasons in this polished simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-feud-usa', 'Playstation', 'Family Feud (USA)', '1995', 'Fighting', 'Tose', '2', '2D fighting', 'Digital adaptation of the famous TV game show.', 'Guess the most popular answers to survey questions to win cash.', 'A faithful recreation of the classic "Survey Says" game show.', 'Family Feud (USA) brings the hit show to your living room. Compete against friends or AI in this social and addictive trivia challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('family-game-pack', 'Playstation', 'Family Game Pack', '1999', 'Action', 'Racjin', '1', 'Action adventure', 'Compilation of various family-oriented mini-games and puzzles.', 'Complete diverse challenges and earn high scores in casual games.', 'A variety-rich package designed for players of all ages.', 'Family Game Pack is the perfect choice for family night. From puzzles to quick action games, there''s something for everyone in this collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-four', 'Playstation', 'Fantastic Four', '2001', 'Racing', 'Atod', '2', 'Arcade motorcycle racing', '3D side-scrolling beat ''em up featuring the iconic Marvel team.', 'Stop Dr. Doom from taking over the world using superhero powers.', 'An early 3D brawler based on the legendary comic book family.', 'Fantastic Four lets you control Mr. Fantastic, Invisible Woman, Thing, and Human Torch. Use their unique abilities to smash through waves of villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fantastic-night-dreams---cotton-original', 'Playstation', 'Fantastic Night Dreams - Cotton Original', '1997', 'Adventure', 'Psygnosis', '1', 'Cinematic adventure', 'Side-scrolling "cute ''em up" shooter with magical themes.', 'Blast through surreal enemies to satisfy Cotton''s craving for candy.', 'A vibrant and challenging port of the arcade magical shooter.', 'Fantastic Night Dreams - Cotton Original features stunning pixel art and intense shooting. Help the witch Cotton on her quest for "Willow" candies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fatal-fury:-wild-ambition', 'Playstation', 'Fatal Fury: Wild Ambition', '2000', 'Action', 'Reflections Interactive', '2', 'Open-world driving', '3D weapon-based fighting game with a 2D plane of movement.', 'Defeat rivals to prove you are the strongest in the Neo Geo world.', 'A transition of the classic Fatal Fury series into the 3D era.', 'Fatal Fury: Wild Ambition brings Terry Bogard and crew into the third dimension. Experience technical combat and high-stakes duels in this SNK hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa---road-to-world-cup-98-usa', 'Playstation', 'FIFA - Road to World Cup 98 (USA)', '1999', 'Action', 'Reflections Interactive', '2', 'Open-world driving', 'Soccer simulation with a focus on the 1998 World Cup qualifying.', 'Qualify for and win the World Cup using international teams.', 'A landmark entry featuring a deep indoor soccer mode and global rosters.', 'FIFA - Road to World Cup 98 is a fan favorite. Experience the road to France with an expansive soundtrack and improved 3D visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-2000', 'Playstation', 'FIFA 2000', '2001', 'Racing', 'Attention to Detail', '2', 'Motorcycle racing simulation', 'High-energy soccer simulation with updated 2000 season rosters.', 'Win leagues and cups using professional clubs from around the world.', 'A fast-paced, arcade-style entry in the long-running soccer series.', 'FIFA 2000 features a massive selection of teams and a fun, accessible gameplay style. Dominate the pitch and score legendary goals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-2001', 'Playstation', 'FIFA 2001', '2000', 'Shooter', 'Nerve Software', '2', 'Third-person shooter', 'Soccer simulation featuring the official 2001 league licenses.', 'Lead your favorite club to glory in the domestic and European seasons.', 'A more polished and realistic take on the beautiful game for PS1.', 'FIFA 2001 introduces better player animations and tactical depth. Manage your team and execute perfect plays in this classic sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-2002', 'Playstation', 'FIFA 2002', '1998', 'Action', 'Nerve Software', '2', 'Third-person shooter', 'Soccer simulation with a focus on the 2002 professional season.', 'Win championships and master the new power-bar shooting system.', 'A refined entry with improved graphics and deeper ball control.', 'FIFA 2002 brings more precision to the pitch. Use the updated passing and shooting mechanics to outplay your rivals on the global stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fifa-soccer-2003', 'Playstation', 'FIFA Soccer 2003', '1995', 'Shooter', 'id Software', '2', 'First-person shooter', 'Fast-paced soccer action with modern 2003 season updates.', 'Dominate the league and win the cup with high-intensity play.', 'One of the final and most polished FIFA entries for the original PS1.', 'FIFA Soccer 2003 offers smooth gameplay and updated rosters. Experience the thrill of professional football with refined controls and AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighter-maker', 'Playstation', 'Fighter Maker', '1998', 'Strategy', 'Westwood Studios', '2', 'Real-time strategy', 'Creative software that allows players to design their own fighters.', 'Build a character from scratch and program their fighting moves.', 'A unique "make-your-own-game" tool for the fighting genre.', 'Fighter Maker gives you the keys to character creation. Design animations, movesets, and styles to create your ultimate 3D brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighters-impact', 'Playstation', 'Fighter''s Impact', '1997', 'Action', 'Omega Force', '2', 'Hack and slash', '3D fighting game with a focus on realistic martial arts.', 'Defeat a roster of diverse fighters to claim the top spot.', 'An arcade port from Taito with smooth 60fps 3D combat.', 'Fighter''s Impact delivers solid, fast-paced fighting mechanics. Master different styles and find the perfect rhythm to knock out your opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-eyes', 'Playstation', 'Fighting Eyes', '2002', 'Platformer', 'Digital Eclipse', '1', '2D platformer', '3D fighting game with unique characters and magic systems.', 'Win the tournament to uncover the secret of the "Fighting Eyes."', 'A niche and colorful 3D fighter with a distinctive visual style.', 'Fighting Eyes offers a fresh perspective on the genre. Battle through diverse arenas and use special abilities to defeat your challengers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-force', 'Playstation', 'Fighting Force', '1996', 'Platformer', 'Shiny Entertainment', '1', '2D platformer', '3D side-scrolling beat ''em up with destructible environments.', 'Fight through the city to stop a corrupt corporation''s coup.', 'A high-octane brawler from the creators of Starwing and Tomb Raider.', 'Fighting Force brings the spirit of "Streets of Rage" into 3D. Smash objects, pick up weapons, and clear the streets in this action classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fighting-force-2', 'Playstation', 'Fighting Force 2', '2000', 'Educational', 'Bay Area Multimedia', '1', 'Educational adventure', 'Third-person action-adventure with stealth and shooting elements.', 'Infiltrate a high-tech facility to stop a global bioweapon threat.', 'A departure from the original, focusing on a single cyborg protagonist.', 'Fighting Force 2 offers a more tactical and exploration-based experience. Use stealth and a massive arsenal to navigate dangerous industrial zones.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-doom', 'Playstation', 'Final Doom', '1998', 'Horror', 'FromSoftware', '1', 'Psychological horror', 'First-person shooter featuring the "Plutonia Experiment" and "TNT" maps.', 'Survive the most difficult levels in the Doom franchise.', 'A massive and challenging expansion of the original Doom experience.', 'Final Doom is for the hardcore fans. Face relentless waves of demons in some of the most complex and lethal level designs ever created.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-anthology---final-fantasy-v', 'Playstation', 'Final Fantasy Anthology - Final Fantasy V', '1999', 'Horror', 'FromSoftware', '1', 'Psychological horror', 'Traditional turn-based JRPG with a deep job-class system.', 'Defeat Exdeath and restore the elemental crystals of the world.', 'The first official Western release of the legendary fifth installment.', 'Final Fantasy V features a flexible job system that allows for endless customization. Explore multiple worlds in this epic and humorous journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-anthology---final-fantasy-vi', 'Playstation', 'Final Fantasy Anthology - Final Fantasy VI', '1999', 'Sports', 'Acclaim Studios Austin', '4', 'Pro wrestling', 'Epic turn-based JRPG with a focus on character-driven narrative.', 'Join the resistance to stop the Empire and the mad clown Kefka.', 'Widely considered one of the greatest RPGs of all time.', 'Final Fantasy VI is a masterpiece of storytelling. Experience an emotional saga with a massive cast of characters and a legendary soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-chronicles---chrono-trigger', 'Playstation', 'Final Fantasy Chronicles - Chrono Trigger', '2000', 'Sports', 'Acclaim Studios Salt Lake City', '4', 'Pro wrestling', 'Turn-based JRPG featuring time travel and multiple endings.', 'Journey through time to fix history and prevent the apocalypse.', 'The legendary SNES classic ported with new cinematic cutscenes.', 'Chrono Trigger is a timeless epic. Join Crono and his friends across the ages in a quest that remains a gold standard for the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-chronicles---final-fantasy-iv', 'Playstation', 'Final Fantasy Chronicles - Final Fantasy IV', '1998', 'Fighting', 'DreamFactory', '2', '3D fighting', 'Traditional turn-based JRPG with a focus on the "Active Time Battle."', 'Lead Cecil on a path of redemption from a dark knight to a paladin.', 'The definitive version of the fourth entry with new FMV sequences.', 'Final Fantasy IV delivers a powerful story of betrayal and heroism. Experience the classic that defined the cinematic RPG on the PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-origins', 'Playstation', 'Final Fantasy Origins', '1998', 'Shooter', 'Square', '1', 'Side-scrolling shooter', 'Compilation featuring the first two games in the legendary series.', 'Lead the Warriors of Light and the rebels to save their worlds.', 'Remastered versions of Final Fantasy I and II with updated graphics.', 'Final Fantasy Origins brings the roots of the series to a new generation. Enjoy updated visuals, music, and gameplay tweaks in this essential collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-tactics', 'Playstation', 'Final Fantasy Tactics', '1998', 'Shooter', 'Raising Hell Software', '2', 'Light gun shooter', 'Turn-based tactical RPG set in the war-torn land of Ivalice.', 'Lead Ramza Beoulve to uncover the truth behind the Lion War.', 'A deep, complex strategy masterpiece with an adult political story.', 'Final Fantasy Tactics is the pinnacle of the SRPG genre. Master the job system and navigate a world of political intrigue and ancient magic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-tactics---the-lion-war-2021', 'Playstation', 'Final Fantasy Tactics - The Lion War 2.021', '1998', 'Racing', 'Magenta Software', '2', 'Arcade racing', 'Fan-enhanced version of the tactical RPG with PSP content and fixes.', 'Uncover the conspiracy behind the war with improved translation.', 'A quality-of-life hack that brings "The War of the Lions" content to PS1.', 'Final Fantasy Tactics - The Lion War 2.021 is the ultimate way to play. Experience new classes and cutscenes in the original PS1 engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-tactics---the-lion-war-2031', 'Playstation', 'Final Fantasy Tactics - The Lion War 2.031', '2001', 'Sports', 'Z-Axis', '2', 'Extreme sports', 'Updated fan-enhanced tactical RPG with balance and content fixes.', 'Navigate the political strife of Ivalice with the definitive patch.', 'A refined version of the Lion War hack with further bug fixes.', 'Final Fantasy Tactics - The Lion War 2.031 offers the most stable and feature-complete version of this legendary strategy epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vii-usa-disc-1', 'Playstation', 'Final Fantasy VII (USA) (Disc 1)', '2000', 'RPG', 'Sunsoft', '1', 'Tactical RPG', 'Epic turn-based JRPG featuring Cloud Strife and the Shinra Corp.', 'Stop Sephiroth from destroying the planet with the Meteor spell.', 'The revolutionary game that brought JRPGs to the global mainstream.', 'Final Fantasy VII (Disc 1) begins the journey in Midgar. Experience the iconic opening acts of a story that changed gaming history forever.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vii-usa-disc-2', 'Playstation', 'Final Fantasy VII (USA) (Disc 2)', '2000', 'Racing', 'Davilex', '2', 'Arcade racing', 'Epic turn-based JRPG featuring Cloud Strife and the Shinra Corp.', 'Chase Sephiroth across the world map and uncover the past.', 'The expansive middle act of the world''s most famous RPG.', 'Final Fantasy VII (Disc 2) takes the stakes to new heights. Explore a vast world, master the Materia system, and witness unforgettable plot twists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-fantasy-vii-usa-disc-3', 'Playstation', 'Final Fantasy VII (USA) (Disc 3)', '2000', 'Action', 'Heavy Iron Studios', '1', 'Action adventure', 'Epic turn-based JRPG featuring Cloud Strife and the Shinra Corp.', 'Descend into the Northern Crater for the final confrontation.', 'The dramatic conclusion to Cloud''s struggle against his destiny.', 'Final Fantasy VII (Disc 3) leads to the ultimate battle. Experience the cinematic finale and the epic conclusion of the struggle for the Planet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('final-round-the', 'Playstation', 'Final Round, The', '1997', 'Fighting', 'Konami', '2', '2D fighting', '3D golf simulation with realistic physics and swing mechanics.', 'Win professional tournaments by mastering wind and terrain.', 'A solid and accessible golf sim for the 32-bit era.', 'The Final Round offers a realistic golfing experience on the PS1. Compete on beautifully rendered courses and perfect your timing to top the leaderboards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('finger-flashing', 'Playstation', 'Finger Flashing', '1998', 'Action', 'SCE Japan Studio', '1', 'Action arcade', 'Fast-paced "Rock-Paper-Scissors" rhythm and puzzle hybrid.', 'Defeat opponents by quickly matching hand symbols to the beat.', 'A quirky, high-energy Japanese puzzle game.', 'Finger Flashing is a unique test of reflexes and rhythm. Master the hand-sign combat to clear stages in this vibrant and fast-paced arcade title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('firebugs', 'Playstation', 'Firebugs', '2002', 'Action', 'Asobo Studio', '2', 'Third-person action', 'Futuristic racing with small, weaponized "Firebug" vehicles.', 'Finish first in high-speed races through twisting 3D tracks.', 'A colorful and chaotic arcade racer for fans of Micro Machines.', 'Firebugs delivers miniature racing mayhem. Use power-ups and navigate inventive tracks to outrun your rivals in this high-energy competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('firestorm:-thunderhawk-2', 'Playstation', 'Firestorm: Thunderhawk 2', '1995', 'Shooter', 'Psygnosis', '1', 'Helicopter combat shooter', 'Combat flight simulation featuring the Thunderhawk helicopter.', 'Complete dangerous military missions across global conflict zones.', 'An explosive helicopter sim with a focus on mission-based action.', 'Firestorm: Thunderhawk 2 puts you in the cockpit of a powerful attack chopper. Engage in intense air-to-ground combat and protect global interests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fishermans-bait---a-bass-challenge', 'Playstation', 'Fisherman''s Bait - A Bass Challenge', '1997', 'Sports', 'Koei', '1', 'Fishing simulation', 'Arcade-style fishing simulation with a focus on bass.', 'Hook and land the heaviest bass to win the tournament challenge.', 'A fun and accessible fishing game with a strong arcade feel.', 'Fisherman''s Bait - A Bass Challenge is perfect for casual anglers. Experience the thrill of the strike and the struggle to reel in trophy-sized bass.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fishermans-bait-2---big-ol-bass', 'Playstation', 'Fisherman''s Bait 2 - Big Ol'' Bass', '1998', 'Sports', 'Koei', '1', 'Fishing simulation', 'Technical fishing simulation with more fish and better physics.', 'Catch legendary "Big Ol'' Bass" in various scenic locations.', 'The expanded sequel to the popular arcade fishing hit.', 'Fisherman''s Bait 2 - Big Ol'' Bass offers more depth and variety. Explore new lakes and use a wider range of lures to become a fishing legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('fist', 'Playstation', 'Fist', '1997', 'Fighting', 'Taito', '2', '3D fighting', '3D fighting game featuring various martial arts styles.', 'Win the underground fighting tournament to prove your skill.', 'A gritty 3D brawler focused on close-quarters combat.', 'Fist (also known as Touki Denshou) delivers technical fighting action. Master complex combos and special moves to dominate your opponents in the arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('flintstones-the---bedrock-bowling-usa', 'Playstation', 'Flintstones, The - Bedrock Bowling (USA)', '2000', 'Sports', 'Vicarious Visions', '4', 'Bowling simulation', 'Bowling simulation featuring characters from The Flintstones.', 'Bowl strikes and spares across various prehistoric-themed lanes.', 'A whimsical and family-friendly bowling game with a cartoon twist.', 'The Flintstones: Bedrock Bowling brings the Stone Age to the lanes. Join Fred and Barney for a fun and colorful take on the classic sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('football-madness', 'Playstation', 'Football Madness', '1996', 'Sports', 'Studio 3', '2', 'Arcade soccer', 'Arcade-style soccer with exaggerated moves and power-ups.', 'Outscore your rivals in chaotic and high-energy football matches.', 'A fun, non-sim soccer game focused on speed and action.', 'Football Madness offers a wacky take on the world''s favorite sport. Use special abilities and fast-paced plays to win the cup in this arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ford-racing', 'Playstation', 'Ford Racing', '1999', 'Racing', 'Razorworks', '2', 'Arcade racing', 'Licensed racing simulation featuring a wide range of Ford cars.', 'Win championships to unlock classic and modern Ford vehicles.', 'A polished racer focusing on the history of the Ford brand.', 'Ford Racing lets you get behind the wheel of iconic cars. Master the tracks and prove your driving skills in this officially licensed racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ford-truck-mania', 'Playstation', 'Ford Truck Mania', '1999', 'Racing', 'Eutechnyx', '2', 'Arcade racing', 'Off-road truck racing featuring Ford''s heavy-duty vehicles.', 'Conquer rugged terrain and win races in powerful Ford trucks.', 'A gritty off-road racer focused on power and suspension.', 'Ford Truck Mania brings the mud and dirt to your screen. Drive legendary Ford trucks through challenging courses and dominate the competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('formula-karts:-special-edition', 'Playstation', 'Formula Karts: Special Edition', '1999', 'Racing', 'Midway', '2', 'Arcade kart racing', '3D kart racing with professional karts and tracks.', 'Win the special edition championship across global karting circuits.', 'A realistic and technical take on kart racing.', 'Formula Karts: Special Edition offers precise handling and high-speed action. Experience the intensity of professional karting in this detailed sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('formula-one-2001-europe-enfi', 'Playstation', 'Formula One 2001 (Europe) (En,Fi)', '2001', 'Racing', 'Bizarre Creations', '2', 'Formula racing simulation', 'Formula One racing with 2001 season rosters and tracks.', 'Lead your team to victory in the 2001 F1 World Championship.', 'The European edition of the premier open-wheel racing sim.', 'Formula One 2001 (En,Fi) delivers authentic F1 excitement. Features realistic car damage and official licensing for an immersive racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('formula-one-2001-europe-frde', 'Playstation', 'Formula One 2001 (Europe) (Fr,De)', '2001', 'Racing', 'Bizarre Creations', '2', 'Formula racing simulation', 'Formula One racing with 2001 season rosters and tracks.', 'Lead your team to victory in the 2001 F1 World Championship.', 'The localized French and German version of the 2001 F1 sim.', 'Formula One 2001 (Fr,De) offers the same high-speed simulation with localized menus and commentary for European regions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('formula-one-arcade', 'Playstation', 'Formula One Arcade', '2002', 'Racing', 'Kuju Entertainment', '2', 'Arcade racing', 'Arcade-style Formula One racing with simplified controls.', 'Navigate chaotic tracks and finish first in fast-paced races.', 'A colorful and accessible F1 game for casual players.', 'Formula One Arcade is all about speed and fun. Enjoy simplified mechanics and vibrant tracks in this high-energy take on the sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('forsaken', 'Playstation', 'Forsaken', '1998', 'Shooter', 'Iguana Entertainment', '2', 'First-person shooter', '360-degree first-person shooter with vehicular movement.', 'Navigate subterranean tunnels and destroy the enemy''s reactor.', 'A gritty, futuristic "6-degrees-of-freedom" shooter.', 'Forsaken delivers intense arena-based combat. Master movement in all directions to survive the post-apocalyptic tunnels of a dying Earth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frank-thomas-big-hurt-baseball', 'Playstation', 'Frank Thomas Big Hurt Baseball', '1996', 'Sports', 'High Voltage Software', '2', 'Baseball simulation', '3D baseball simulation featuring a legendary power hitter.', 'Lead your team to the World Series using professional tactics.', 'A solid baseball sim with digitized player sprites.', 'Frank Thomas Big Hurt Baseball offers a deep sports experience. Master the plate and the mound in this realistic 32-bit baseball title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('freestyle-motocross---mcgrath-vs-pastrana', 'Playstation', 'Freestyle Motocross - McGrath vs. Pastrana', '2000', 'Sports', 'Z-Axis', '2', 'Motocross racing', 'Freestyle motocross simulation with tricks and stunts.', 'Score points by performing massive air tricks and winning races.', 'A high-flying motocross game featuring top pro riders.', 'Freestyle Motocross - McGrath vs. Pastrana pits two legends against each other. Pull off insane stunts and dominate the dirt in this extreme sports hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger', 'Playstation', 'Frogger', '1997', 'Platformer', 'Millennium Interactive', '1', 'Arcade platformer', 'Modernized 3D update of the classic arcade crossing game.', 'Guide Frogger safely through traffic and hazards to his home.', 'A colorful and challenging remake of the arcade legend.', 'Frogger on PS1 brings the classic gameplay into a new dimension. Navigate diverse worlds and dodge dangers in this addictive 3D update.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('frogger-2:-swampys-revenge', 'Playstation', 'Frogger 2: Swampy''s Revenge', '2000', 'Platformer', 'Blitz Games', '1', '3D platformer', '3D platformer featuring Frogger with new moves and worlds.', 'Rescue the baby frogs from the evil crocodile Swampy.', 'An expanded sequel with more variety and better movement.', 'Frogger 2: Swampy''s Revenge offers more levels and playable characters. Experience refined 3D platforming in this charming arcade sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('from-tv-animation-one-piece---grand-battle!-2-japan', 'Playstation', 'From TV Animation One Piece - Grand Battle! 2 (Japan)', '2002', 'Fighting', 'Ganbarion', '2', '3D arena fighting', '3D arena-based fighting game based on the One Piece anime.', 'Defeat rivals using iconic moves from the Alabasta arc.', 'A vibrant and chaotic fighter with plenty of anime fanservice.', 'One Piece - Grand Battle! 2 brings the Straw Hat crew to life. Use Luffy’s rubber powers and Zoro’s swords to win the ultimate pirate brawl.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-2-english-patched', 'Playstation', 'Front Mission 2 (English Patched)', '1997', 'Strategy', 'Square', '1', 'Tactical RPG', 'Turn-based tactical RPG with giant customizable robots (Wanzers).', 'Lead a military unit to victory in a gritty political conflict.', 'The fan-translated version of the classic tactical sequel.', 'Front Mission 2 (English Patched) allows Western fans to experience the deep story and complex Wanzer customization of this strategic masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('front-mission-3', 'Playstation', 'Front Mission 3', '1999', 'Strategy', 'Square', '1', 'Tactical RPG', 'Turn-based tactical strategy with branching narratives.', 'Uncover a global conspiracy while managing a squad of Wanzers.', 'One of the most acclaimed tactical RPGs on the PlayStation.', 'Front Mission 3 features two massive storylines and deep robot customization. Outsmart your enemies on the grid in this legendary strategy epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('g-darius-usa', 'Playstation', 'G-Darius (USA)', '1998', 'Shooter', 'Taito', '2', 'Side-scrolling shooter', '2.5D side-scrolling shooter with massive bosses and paths.', 'Blast through biological enemies to save the galaxy from the Thiima.', 'A visually stunning port of the legendary arcade "shmup."', 'G-Darius features a unique "Capture Ball" system. Absorb your enemies to use their power in this masterpiece of the shooter genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaga:-destination-earth', 'Playstation', 'Galaga: Destination Earth', '1999', 'Shooter', 'Hasbro Interactive', '2', 'Arcade shooter', 'Fixed-screen and 3D shooter based on the classic Galaga.', 'Defend Earth from swarms of alien invaders across the solar system.', 'A modernized update of the foundational arcade shooter.', 'Galaga: Destination Earth brings the bug-blasting action into the 32-bit era. Experience classic and new gameplay modes in this intergalactic challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galaxy-fight', 'Playstation', 'Galaxy Fight', '1995', 'Fighting', 'Sunsoft', '2', '2D fighting', '2D fighting game featuring characters from various planets.', 'Defeat all challengers to stop the cosmic threat, Felden.', 'A fast-paced Sunsoft fighter with impressive zoom effects.', 'Galaxy Fight offers unique characters and high-energy combat. Experience the arcade classic with smooth animations and diverse fighting styles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('galerians-usa', 'Playstation', 'Galerians (USA)', '1999', 'Horror', 'Polygon Magic', '1', 'Survival horror', 'Psychological survival horror with a focus on psychic combat.', 'Escaped the facility and uncover the truth about the Galerians.', 'A dark, mature horror game with a unique "drugs/powers" system.', 'Galerians is a cult classic survival horror. Use terrifying psychic abilities instead of guns to survive a dystopian nightmare in this tense adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gauntlet-legends', 'Playstation', 'Gauntlet Legends', '2000', 'Action', 'Atari Games', '4', 'Top-down action', '3D hack-and-slash dungeon crawler with cooperative play.', 'Defeat the demon Skorne and recover the lost magical realms.', 'The legendary arcade fantasy brawler ported to the PS1.', 'Gauntlet Legends offers addictive co-op action. Choose your class, level up, and fight through swarms of monsters in this classic quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gear-fighter-dendoh', 'Playstation', 'Gear Fighter Dendoh', '2001', 'Action', 'Banpresto', '2', 'Anime action fighting', '2D side-scrolling action game based on the mecha anime.', 'Pilot the Dendoh robot to defeat the mechanical Gulfer empire.', 'A high-energy action title with impressive sprite work.', 'Gear Fighter Dendoh captures the spirit of the anime. Use powerful "Data Weapon" attacks to smash through robot hordes in this fast-paced brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gegege-no-kitarou', 'Playstation', 'GeGeGe no Kitarou', '1999', 'Adventure', 'KCE Tokyo', '1', 'Action adventure', '2D side-scrolling platformer based on the classic yokai manga.', 'Fight through hordes of ghosts and monsters to protect humanity.', 'A charming and atmospheric game rooted in Japanese folklore.', 'GeGeGe no Kitarou brings the world of Kitaro to the PS1. Use traditional yokai powers to solve puzzles and defeat legendary spirits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekido:-urban-fighters', 'Playstation', 'Gekido: Urban Fighters', '1999', 'Action', 'Natsume', '2', 'Beat ''em up', '3D side-scrolling beat ''em up with a stylish urban aesthetic.', 'Fight through street gangs to save the city from a crime lord.', 'A gritty and technical brawler with deep combat mechanics.', 'Gekido: Urban Fighters offers intense martial arts action. Master combos and use the environment to clear the streets in this stylish brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekioh:-shooting-king', 'Playstation', 'Gekioh: Shooting King', '1999', 'Shooter', 'Xing', '2', 'Vertical shooter', 'Vertical-scrolling "shmup" with a focus on cinematic boss battles.', 'Blast through enemy forces to save the kingdom from destruction.', 'A polished and intense shooter with high-quality 2D art.', 'Gekioh: Shooting King (also known as Shienryu) is a classic arcade shooter. Experience massive firepower and intricate bullet patterns in this "shmup" gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gekitou!-crush-gear-turbo', 'Playstation', 'Gekitou! Crush Gear Turbo', '2002', 'Action', 'Takara', '2', 'Anime arena fighting', '3D vehicular combat/racing featuring "Crush Gear" machines.', 'Win the tournament by knocking rivals out of the circular arena.', 'A fun adaptation of the toy and anime franchise.', 'Gekitou! Crush Gear Turbo lets you customize and battle your gears. Master the art of the spin-out to become the champion in this competitive hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('genei-tougi:-shadow-struggle', 'Playstation', 'Genei Tougi: Shadow Struggle', '1996', 'Fighting', 'Konami', '2', '3D fighting', '3D fighting game with a focus on shadow-boxing and silhouettes.', 'Defeat all rivals in a high-stakes martial arts competition.', 'A visually unique fighter with a dark, atmospheric style.', 'Genei Tougi: Shadow Struggle (also known as Shadow Struggle) offers technical 3D combat. Master the art of the counter in this stylish and rare brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gensou-suikoden-japan', 'Playstation', 'Gensou Suikoden (Japan)', '1995', 'RPG', 'Konami', '1', 'JRPG', 'Traditional turn-based JRPG featuring 108 recruitable characters.', 'Lead a rebel army to overthrow the corrupt Scarlet Moon Empire.', 'The foundational entry in the legendary Suikoden series.', 'Gensou Suikoden is a masterpiece of storytelling. Build your castle, recruit the 108 Stars of Destiny, and change history in this epic RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gensou-suikoden-ii-japan', 'Playstation', 'Gensou Suikoden II (Japan)', '1998', 'RPG', 'Konami', '1', 'JRPG', 'Traditional turn-based JRPG featuring tactical army battles.', 'Lead a new generation of heroes to stop a brutal war between nations.', 'The Japanese version of one of the greatest JRPGs ever made.', 'Gensou Suikoden II is a masterpiece of political intrigue and emotional storytelling. Recruit the 108 Stars of Destiny and build your fortress in this epic sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('geom-cube', 'Playstation', 'Geom Cube', '1998', 'Puzzle', 'Taito', '2', 'Geometric puzzle', '3D block-matching puzzle game with a competitive edge.', 'Rotate and place 3D shapes to clear layers in a wireframe arena.', 'A unique 32-bit evolution of the Tetris-style puzzle formula.', 'Geom Cube challenges your spatial awareness. Compete against the clock or a friend in this deep and addictive 3D puzzle experience on PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gex', 'Playstation', 'Gex', '1995', 'Platformer', 'Crystal Dynamics', '1', '2D platformer', '2D side-scrolling platformer starring a wisecracking gecko.', 'Navigate through media-themed worlds to defeat the evil Rez.', 'A classic 2D platformer known for its humor and pop-culture puns.', 'Gex brings attitude to the PlayStation. Explore levels inspired by horror, cartoons, and kung-fu movies while using your tongue and tail to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gex---enter-the-gecko', 'Playstation', 'Gex - Enter the Gecko', '1998', 'Platformer', 'Crystal Dynamics', '1', '3D platformer', '3D platformer with exploration and mission-based gameplay.', 'Collect remotes across various TV-themed 3D environments.', 'Gex''s jump into the third dimension with a focus on exploration.', 'Gex - Enter the Gecko features huge 3D worlds and hilarious celebrity impressions. Master the gecko''s climbing abilities to stop Rez''s return.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gex-3:-deep-cover-gecko', 'Playstation', 'Gex 3: Deep Cover Gecko', '1999', 'Platformer', 'Crystal Dynamics', '1', '3D platformer', '3D platformer with gadgets, costumes, and stealth elements.', 'Rescue Agent Xtra and stop Rez''s final plan in the Media Dimension.', 'The most polished and content-rich entry in the Gex trilogy.', 'Gex 3: Deep Cover Gecko offers diverse gameplay, from flying to tank combat. Use special suits and gadgets to master this definitive 3D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ghost-in-the-shell', 'Playstation', 'Ghost in the Shell', '1997', 'Action', 'Exact', '1', 'Third-person shooter', 'Third-person vehicular shooter featuring the Fuchikoma tank.', 'Infiltrate enemy sectors and neutralize a high-tech terrorist threat.', 'A fast-paced shooter based on the legendary cyberpunk manga.', 'Ghost in the Shell offers wall-crawling action and intense shooting. Pilot the agile Think-Tank through futuristic urban environments in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('glover', 'Playstation', 'Glover', '1998', 'Platformer', 'Hasbro Interactive', '1', '3D platformer', '3D puzzle-platformer where you control a sentient four-fingered glove.', 'Navigate complex worlds to recover the lost magical crystals.', 'A creative platformer focused on ball-physics and manipulation.', 'Glover is a unique challenge where you must protect your ball at all costs. Master rolling, bouncing, and throwing to solve environmental puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gokujou-parodius-da!-deluxe-pack-japan', 'Playstation', 'Gokujou Parodius Da! Deluxe Pack (Japan)', '1996', 'Shooter', 'Konami', '2', 'Arcade shooter', 'Collection of two legendary surreal side-scrolling shooters.', 'Blast through absurd enemies in a parody of the Gradius series.', 'A colorful and hilarious "shmup" pack with incredible music.', 'Gokujou Parodius Da! Deluxe Pack brings the weirdest shooters to PS1. Face dancing pandas and giant penguins in this high-energy arcade compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gold-and-glory---the-road-to-el-dorado', 'Playstation', 'Gold and Glory - The Road to El Dorado', '2000', 'Adventure', 'Revolution Software', '1', 'Action adventure', '3D action-adventure based on the DreamWorks animated film.', 'Guide Tulio and Miguel to find the legendary city of gold.', 'A faithful adaptation featuring puzzles and stealth segments.', 'Gold and Glory - The Road to El Dorado captures the charm of the movie. Navigate the jungle and escape the Spanish army in this cinematic quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gold-and-glory---the-road-to-el-dorado-usa', 'Playstation', 'Gold and Glory - The Road to El Dorado (USA)', '2000', 'Adventure', 'Revolution Software', '1', 'Action adventure', '3D action-adventure based on the DreamWorks animated film.', 'Guide Tulio and Miguel to find the legendary city of gold.', 'A faithful adaptation featuring puzzles and stealth segments.', 'Gold and Glory - The Road to El Dorado (USA) offers a lighthearted adventure for all ages. Solve environmental puzzles and uncover ancient secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gouketuji-ichizoku-2:-chottodake-saikyou-densetsu', 'Playstation', 'Gouketuji Ichizoku 2: Chottodake Saikyou Densetsu', '1995', 'Fighting', 'Atlus', '2', '2D fighting', '2D fighting game featuring a bizarre cast and unique special moves.', 'Win the tournament to prove your family''s fighting superiority.', 'A refined and chaotic entry in the Power Instinct series.', 'Gouketuji Ichizoku 2: Chottodake Saikyou Densetsu features over-the-top characters and fast-paced combat. Experience the wild energy of this Japanese fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gradius-gaiden-japan', 'Playstation', 'Gradius Gaiden (Japan)', '1997', 'Shooter', 'Konami', '1', 'Side-scrolling shooter', 'Side-scrolling space shooter with customizable weapon systems.', 'Destroy the core of enemy fortresses to save the galaxy.', 'Widely considered the best "shmup" on the PlayStation.', 'Gradius Gaiden (Japan) offers incredible graphics and four unique ships. Master the legendary "Option" system in this high-intensity space odyssey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gran-turismo', 'Playstation', 'Gran Turismo', '1997', 'Racing', 'Polyphony Digital', '2', 'Driving simulation', 'Realistic car racing simulation with licensed vehicles.', 'Win races to earn credits, buy new cars, and upgrade parts.', 'The game that revolutionized the racing genre with its realism.', 'Gran Turismo features over 100 licensed cars and a deep career mode. Master the physics of real driving in the definitive PlayStation racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gran-turismo-2-usa-arcade-mode', 'Playstation', 'Gran Turismo 2 (USA) (Arcade Mode)', '1999', 'Racing', 'Polyphony Digital', '2', 'Driving simulation', 'Arcade-style racing focused on high-speed thrills and instant action.', 'Compete in quick races and trials with unlocked vehicles.', 'The "action" focused disc of the massive Gran Turismo 2 package.', 'Gran Turismo 2 (Arcade Mode) offers immediate racing fun. Choose from a vast roster of cars and tracks for high-octane competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gran-turismo-2-usa-simulation-mode', 'Playstation', 'Gran Turismo 2 (USA) (Simulation Mode)', '1999', 'Racing', 'Polyphony Digital', '2', 'Driving simulation', 'In-depth car culture simulation featuring nearly 500 vehicles.', 'Build your garage and win professional championships worldwide.', 'The deepest and most expansive racing experience of the 32-bit era.', 'Gran Turismo 2 (Simulation Mode) is a car lover''s dream. Buy, tune, and race everything from street cars to rally legends in this massive sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grand-theft-auto', 'Playstation', 'Grand Theft Auto', '1997', 'Action', 'DMA Design', '2', 'Top-down action', 'Top-down open-world action with a focus on criminal missions.', 'Complete jobs for various gangs to earn money and respect.', 'The controversial and revolutionary beginning of the GTA saga.', 'Grand Theft Auto offers total freedom to explore three massive cities. Steal cars, complete hits, and cause mayhem in this arcade-style crime sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grand-theft-auto-2', 'Playstation', 'Grand Theft Auto 2', '1999', 'Action', 'DMA Design', '2', 'Top-down action', 'Top-down open-world action with a futuristic setting.', 'Work for rival factions to become the top criminal in the city.', 'An expanded sequel with improved visuals and gang reputation.', 'Grand Theft Auto 2 takes the carnage to the future. Master the "Respect" system and navigate the dangerous streets of Anywhere City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grand-theft-auto:-london-1969', 'Playstation', 'Grand Theft Auto: London 1969', '1999', 'Action', 'DMA Design', '2', 'Top-down action', 'Top-down open-world action set in a 1960s period aesthetic.', 'Complete criminal missions across the streets of historical London.', 'A stylish expansion pack with unique cars and British charm.', 'Grand Theft Auto: London 1969 brings the classic gameplay to a new setting. Experience the mod culture and groovy vibes in this retro crime spree.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grid-runner', 'Playstation', 'Grid Runner', '1996', 'Shooter', 'Llamasoft', '1', 'Arcade shooter', 'Fast-paced 3D action-puzzler with a futuristic theme.', 'Capture enemies using a magic lasso to clear the arena.', 'A high-energy "tag" style game with a unique movement system.', 'Grid Runner offers a blend of speed and strategy. Outmaneuver your opponents in a variety of 3D grids in this fast-paced arcade challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grinch-the', 'Playstation', 'Grinch, The', '2000', 'Platformer', 'Artificial Mind & Movement', '1', '3D platformer', 'Stealth-based 3D adventure featuring the holiday-hating Grinch.', 'Ruin Christmas for the Whos by stealing their presents and decorations.', 'A funny and faithful adaptation of the classic Dr. Seuss story.', 'The Grinch features gadgets and stealthy gameplay. Sneak through Whoville and use the Grinch''s bag of tricks to stop the holiday in this festive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grind-session', 'Playstation', 'Grind Session', '2000', 'Sports', 'Z-Axis', '2', 'Skateboarding', 'Professional skateboarding simulation with a focus on style.', 'Complete trick-based objectives across urban skate parks.', 'A technical skateboarding game featuring pro riders and a hip-hop vibe.', 'Grind Session offers a realistic take on skate culture. Master technical lines and huge air tricks in this atmospheric and challenging sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('grudge-warriors', 'Playstation', 'Grudge Warriors', '1998', 'Racing', 'Team17', '2', 'Combat racing', 'Vehicular combat in post-apocalyptic arenas.', 'Destroy all rival vehicles using an array of heavy weaponry.', 'A gritty and explosive car combat game in the vein of Twisted Metal.', 'Grudge Warriors delivers high-octane destruction. Choose your armored vehicle and blast your way to victory in this metal-crunching arena battler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gt-straight-victory---hoshino-kazuyoshi-e-no-chousen', 'Playstation', 'GT Straight Victory - Hoshino Kazuyoshi e no Chousen', '1997', 'Racing', 'Genki', '2', 'Arcade racing', 'Realistic 3D circuit racing simulation.', 'Win the GT championship by mastering professional driving lines.', 'A focused racing title endorsed by legendary driver Kazuyoshi Hoshino.', 'GT Straight Victory offers a technical challenge for racing fans. Tune your car and compete on authentic tracks in this high-speed simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guardians-crusade-usa', 'Playstation', 'Guardian''s Crusade (USA)', '1999', 'RPG', 'Tamsoft', '1', 'Action RPG', 'Traditional turn-based JRPG with a colorful, lighthearted style.', 'Guide Knight and his companions to stop a dark magic threat.', 'A charming and accessible JRPG with a unique monster-raising mechanic.', 'Guardian''s Crusade features vibrant 3D graphics and a classic quest. Train your "Living Toy" companion and explore a world of wonder in this RPG gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gubble', 'Playstation', 'Gubble', '1998', 'Puzzle', 'Actual Entertainment', '1', 'Physics puzzle', '3D puzzle-platformer featuring a bubble-trapped protagonist.', 'Navigate maze-like levels to collect items while avoiding enemies.', 'A cute and challenging game focused on precision and timing.', 'Gubble is a fun and accessible puzzler for all ages. Use your drill to clear paths and solve puzzles in this vibrant 3D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guilty-gear', 'Playstation', 'Guilty Gear', '1998', 'Fighting', 'Arc System Works', '2', '2D fighting', 'High-speed 2D fighting game with a heavy metal aesthetic.', 'Win the tournament to stop the resurrection of a powerful gear.', 'The legendary debut of the most stylish fighting franchise.', 'Guilty Gear features fluid animation and the unique "Instant Kill" system. Experience the high-octane beginnings of Sol Badguy and Ky Kiske.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('guitar-freaks-japan', 'Playstation', 'Guitar Freaks (Japan)', '1999', 'Music', 'Konami', '2', 'Rhythm game', 'Rhythm-based music game using a specialized guitar controller.', 'Play the notes in time with the music to simulate a rock star performance.', 'The foundational game of the guitar-rhythm genre.', 'Guitar Freaks (Japan) brings the arcade rock experience home. Master the plastic guitar and play along to high-energy J-rock and pop hits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gundam---the-battle-master', 'Playstation', 'Gundam - The Battle Master', '1996', 'Fighting', 'Natsume', '2', '2D fighting', '2D fighting game featuring giant mechs from the Gundam series.', 'Defeat other Mobile Suits in a high-stakes robot tournament.', 'A technical mech-fighter with impressive sprite work and scale.', 'Gundam - The Battle Master offers deep customization and heavy-hitting combat. Experience the power of Mobile Suits in this tactical 2D fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gundam---the-battle-master-2', 'Playstation', 'Gundam - The Battle Master 2', '1997', 'Fighting', 'Natsume', '2', '2D fighting', 'Refined 2D mech fighting with more characters and better visuals.', 'Win the ultimate war between mechas and pilot your favorite suit.', 'The definitive sequel to the first Battle Master title.', 'Gundam - The Battle Master 2 features smoother animations and a massive roster. Master the "thruster" mechanics and dominate the robot arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gundam-battle-assault-2', 'Playstation', 'Gundam Battle Assault 2', '2002', 'Fighting', 'Natsume', '2', '2D fighting', 'High-energy 2D mecha brawler with a massive roster.', 'Battle through the "Street Mode" to prove you are the best pilot.', 'A localized and polished version of Battle Master 2 for the West.', 'Gundam Battle Assault 2 brings the ultimate anime robot war to PS1. Featuring characters from Wing and G Gundam, it is the peak of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gundam:-battle-assault', 'Playstation', 'Gundam: Battle Assault', '2000', 'Fighting', 'Natsume', '2', '2D fighting', '2D weapon-based fighting game with giant Mobile Suits.', 'Defeat rival pilots in the Mobile Suit tournament.', 'A heavy-hitting 2D fighter featuring iconic Gundam designs.', 'Gundam: Battle Assault offers strategic combat with massive robots. Use special attacks and manage your energy to defeat your opponents in this anime hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunfighter---the-legend-of-jesse-james', 'Playstation', 'Gunfighter - The Legend of Jesse James', '1998', 'Shooter', 'Rebellion Developments', '1', 'Light gun shooter', 'Light-gun shooter set in the American Wild West.', 'Take down outlaws and bring justice to the frontier as Jesse James.', 'A fast-paced shooter that supports the Guncon peripheral.', 'Gunfighter - The Legend of Jesse James delivers authentic western action. Master your draw and clear out gangs in this high-stakes arcade shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gungage', 'Playstation', 'Gungage', '1999', 'Shooter', 'Konami', '2', 'Arcade shooter', 'Third-person action-adventure with a mix of shooting and platforming.', 'Fight through diverse levels to stop an evil technological threat.', 'A visually impressive and fast-paced action game from Japan.', 'Gungage features multiple playable characters and high-octane shooting. Experience a stylish sci-fi adventure with large bosses and intense combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunners-heaven', 'Playstation', 'Gunner''s Heaven', '1996', 'Action', 'Project Horned Owl', '1', 'Run and gun', '2D side-scrolling run-and-gun shooter with explosive action.', 'Blast through waves of enemies to save the kingdom from a coup.', 'Often called the "Gunstar Heroes" of the PlayStation.', 'Gunner''s Heaven (also known as Rapid Reload) offers non-stop 2D shooting. Choose your hero and use a variety of weapons to defeat massive mechanical bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunpey', 'Playstation', 'Gunpey', '1999', 'Puzzle', 'Bandai', '1', 'Logic puzzle', 'Abstract logic puzzle game involving matching lines.', 'Connect lines on moving tiles to clear them from the board.', 'A stylish and addictive puzzler designed by Gunpei Yokoi.', 'Gunpey is a test of speed and spatial logic. Clear the screen by building continuous lines in this unique and rhythmic puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('gunship', 'Playstation', 'Gunship', '1997', 'Simulation', 'MicroProse', '1', 'Helicopter combat simulation', 'Combat flight simulation featuring the AH-64 Apache helicopter.', 'Complete dangerous military operations and eliminate ground targets.', 'A realistic and tactical helicopter combat simulator.', 'Gunship on PS1 delivers authentic aerial warfare. Manage your systems and weapon loadouts to complete high-stakes missions in various global conflict zones.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hard-boiled', 'Playstation', 'Hard Boiled', '1997', 'Action', 'Genki', '1', 'Third-person action', 'Side-scrolling 2D action game with shooting and platforming.', 'Fight through a dystopian city to stop a criminal organization.', 'A gritty and fast-paced action game based on the Hong Kong film style.', 'Hard Boiled features intense gunfights and smooth 2D animation. Channel your inner action hero to take down hordes of enemies in this stylish urban brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hardball-5', 'Playstation', 'HardBall 5', '1991', 'Sports', 'MindSpan', '2', 'Baseball simulation', '3D baseball simulation with realistic stats and management.', 'Lead your team to the championship using professional strategy.', 'A classic and detailed baseball sim for sports enthusiasts.', 'HardBall 5 offers deep gameplay with comprehensive team management. Master the mound and the plate in this realistic 32-bit baseball experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harmful-park', 'Playstation', 'Harmful Park', '1997', 'Shooter', 'Sky Think System', '2', 'Vertical shoot ''em up', 'Side-scrolling "cute ''em up" shooter with surreal themes.', 'Save the park from a scientist using food and toy-themed weapons.', 'A colorful, rare, and whimsical Japanese shooter.', 'Harmful Park is a masterpiece of 2D pixel art. Navigate through a bizarre amusement park and battle absurd bosses in this charming and fun "shmup."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-chamber-of-secrets-usa-enfres', 'Playstation', 'Harry Potter and the Chamber of Secrets (USA) (En,Fr,Es)', '2002', 'Action', 'Argonaut Games', '1', 'Action adventure', '3D action-adventure with magic spells, puzzles, and flying.', 'Uncover the mystery of the Chamber and defeat the heir of Slytherin.', 'The magical sequel featuring improved graphics and more exploration.', 'Harry Potter and the Chamber of Secrets brings Hogwarts to life. Master new spells, play Quidditch, and explore the castle secrets in this faithful adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-philosophers-stone-europe-enfrde', 'Playstation', 'Harry Potter and the Philosopher''s Stone (Europe) (En,Fr,De)', '2001', 'Action', 'Argonaut Games', '1', 'Action adventure', '3D action-adventure following the story of the first book.', 'Help Harry survive his first year at Hogwarts and stop Voldemort.', 'The European edition of the foundational wizarding world adventure.', 'Experience the magic of the boy who lived. Solve puzzles, attend classes, and face the dark arts in this enchanting 3D journey through Hogwarts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harry-potter-and-the-sorcerers-stone-usa-enfres', 'Playstation', 'Harry Potter and the Sorcerer''s Stone (USA) (En,Fr,Es)', '2001', 'Action', 'Argonaut Games', '1', 'Action adventure', '3D action-adventure following the story of the first book.', 'Help Harry survive his first year at Hogwarts and stop Voldemort.', 'The North American release of the first Harry Potter adventure.', 'Harry Potter and the Sorcerer''s Stone lets you explore Hogwarts. Master spells like Flipendo and Wingardium Leviosa to overcome challenges in this classic hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('harvest-moon---back-to-nature', 'Playstation', 'Harvest Moon - Back to Nature', '1999', 'Simulation', 'Victor Interactive Software', '1', 'Farming simulation', 'Life simulation RPG with farming, social, and building elements.', 'Restore your grandfather''s farm and build relationships in the village.', 'Widely considered one of the best farming sims of all time.', 'Harvest Moon - Back to Nature offers a deep and relaxing experience. Plant crops, raise livestock, and find love in Mineral Town in this iconic RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('haunted-junction-seitokai-batch-o-oe!', 'Playstation', 'Haunted Junction Seitokai Batch o Oe!', '1997', 'Adventure', 'Atlus', '1', 'Visual novel adventure', 'Point-and-click adventure based on the supernatural comedy anime.', 'Solve ghostly mysteries around the school with the Student Council.', 'A quirky Japanese adventure filled with humor and spirits.', 'Haunted Junction Seitokai Batch o Oe! captures the charm of the anime. Use logic and dialogue to manage the supernatural occurrences in this unique title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heart-of-darkness-usa', 'Playstation', 'Heart of Darkness (USA)', '1998', 'Adventure', 'Amazing Studio', '1', 'Cinematic platform adventure', 'Cinematic 2D platformer with high-quality animation and puzzles.', 'Rescue your dog, Whisky, from a world of dark shadows.', 'A visual masterpiece from the creator of Rayman.', 'Heart of Darkness features fluid animation and a dark atmosphere. Navigate a dangerous alien world and solve environmental puzzles to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('heberekes-popoitto', 'Playstation', 'Hebereke''s Popoitto', '1997', 'Puzzle', 'Sunsoft', '2', 'Competitive puzzle', 'Competitive block-matching puzzle game with cute characters.', 'Match blocks to clear the board and outscore your opponent.', 'A vibrant and addictive Japanese puzzle title.', 'Hebereke''s Popoitto is a test of speed and planning. Enjoy colorful visuals and frantic gameplay in this classic entry of the Hebereke series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hellboy---asylum-seeker', 'Playstation', 'Hellboy - Asylum Seeker', '2000', 'Action', 'Cryo Interactive', '1', 'Action adventure', 'Third-person action-adventure with a focus on dark atmosphere.', 'Investigate an asylum and stop a ritual to summon ancient evil.', 'A supernatural action game starring the legendary Dark Horse hero.', 'Hellboy - Asylum Seeker brings the comic''s dark tone to PS1. Use Hellboy’s strength and the Good Samaritan to fight demonic forces in this eerie quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hellnight', 'Playstation', 'Hellnight', '1998', 'Horror', 'FromSoftware', '1', 'Psychological horror', 'First-person survival horror focusing on exploration and hiding.', 'Navigate the Tokyo subway and survive the pursuit of monsters.', 'A tense, non-combat horror game with a dark urban setting.', 'Hellnight (known as Tokyo Nightmare) is a cult classic. Escape from an evolving creature in the claustrophobic tunnels beneath the city in this suspenseful title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hello-kitty---cube-frenzy', 'Playstation', 'Hello Kitty - Cube Frenzy', '2000', 'Party', 'Sanrio', '2', 'Party minigames', 'Falling-block puzzle game featuring Sanrio characters.', 'Match colored cubes to clear the screen and help Hello Kitty.', 'A cute and accessible puzzle game for fans of all ages.', 'Hello Kitty - Cube Frenzy offers simple yet addictive gameplay. Help Kitty navigate through various themed levels in this colorful and charming puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('henry-explorers-japan', 'Playstation', 'Henry Explorers (Japan)', '1996', 'Adventure', 'Human Entertainment', '1', 'Point-and-click adventure', 'First-person light-gun shooter with a high-tech theme.', 'Blast through waves of robotic enemies to complete missions.', 'A fast-paced arcade shooter from the makers of Lethal Enforcers.', 'Henry Explorers (also known as Crypt Killer) brings classic arcade shooting to your TV. Use various weapons to clear out monsters in this high-energy hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hercs-adventures-europe', 'Playstation', 'Herc''s Adventures (Europe)', '1997', 'Action', 'LucasArts', '2', 'Top-down action adventure', 'Top-down action-adventure with humor and cooperative play.', 'Journey through ancient Greece to rescue Persephone from Hades.', 'A vibrant and funny adventure from the creators of LucasArts.', 'Herc''s Adventures (Europe) lets you play as Hercules, Atlanta, or Jason. Fight mythological bosses and explore a huge world in this colorful classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hercs-adventures-france', 'Playstation', 'Herc''s Adventures (France)', '1997', 'Action', 'LucasArts', '2', 'Top-down action adventure', 'Top-down action-adventure with humor and cooperative play.', 'Journey through ancient Greece to rescue Persephone from Hades.', 'The localized French version of the epic Greek adventure.', 'Herc''s Adventures (France) offers the same high-energy mythological fun with localized dialogue and text for French-speaking fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hercs-adventures-usa', 'Playstation', 'Herc''s Adventures (USA)', '1997', 'Action', 'LucasArts', '2', 'Top-down action adventure', 'Top-down action-adventure with humor and cooperative play.', 'Journey through ancient Greece to rescue Persephone from Hades.', 'The original North American release of the hit adventure game.', 'Herc''s Adventures (USA) is a masterpiece of 2D action. Use unique items and teamwork to defeat the gods in this hilarious and challenging journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hexen:-beyond-heretic', 'Playstation', 'Hexen: Beyond Heretic', '1997', 'Shooter', 'Raven Software', '2', 'First-person shooter', 'First-person shooter/RPG hybrid with a dark fantasy setting.', 'Defeat the Serpent Riders to save the world of Cronos.', 'A dark and atmospheric FPS featuring three distinct classes.', 'Hexen: Beyond Heretic brings a fantasy twist to the Doom engine. Use magic, axes, and hammers to survive trap-filled dungeons and powerful foes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hi-octane', 'Playstation', 'Hi-Octane', '1995', 'Racing', 'Psygnosis', '2', 'Futuristic racing', 'Futuristic combat racing with high speeds and heavy weapons.', 'Win races and destroy opponents using hover-vehicles.', 'A fast-paced arcade racer from the creators of Bullfrog.', 'Hi-Octane offers a gritty take on futuristic driving. Master your hover-tank and use speed boosts and missiles to dominate the track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('high-heat-major-league-baseball-2002', 'Playstation', 'High Heat Major League Baseball 2002', '2001', 'Sports', '3DO', '2', 'Baseball simulation', 'Realistic 3D baseball simulation with licensed MLB players.', 'Lead your favorite major league team to the World Series.', 'A technical baseball game with deep stats and realistic physics.', 'High Heat Major League Baseball 2002 delivers an authentic diamond experience. Master the art of pitching and hitting in this polished sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hogs-of-war', 'Playstation', 'Hogs of War', '2000', 'Strategy', 'Worms Team 17', '4', 'Turn-based strategy', 'Turn-based tactical strategy with 3D terrain and humor.', 'Command a squad of pigs to conquer territories in a global war.', 'A comedic and strategic game often called "Worms with Pigs."', 'Hogs of War features hilarious voice acting and deep tactical combat. Customize your squad and use diverse weapons to win the Pork-a-lypse.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hokuto-no-ken:-seiki-matsukyu-seishi-densetsu-japan', 'Playstation', 'Hokuto no Ken: Seiki Matsukyu Seishi Densetsu (Japan)', '1996', 'Fighting', 'Toei Animation', '2', '2D fighting', '2D side-scrolling beat ''em up based on the classic anime.', 'Fight through post-apocalyptic gangs as Kenshiro.', 'A cinematic brawler that captures the intensity of the series.', 'Hokuto no Ken (Fist of the North Star) features explosive martial arts. Use Kenshiro’s pressure-point techniques to defeat rivals in this faithful adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hooters-road-trip', 'Playstation', 'Hooters Road Trip', '2001', 'Racing', 'Vision Scape Interactive', '2', 'Arcade racing', 'Arcade-style racing featuring Hooters-themed girls and tracks.', 'Win races across the USA to unlock gallery items and new cars.', 'A casual and accessible racer with a focus on Americana.', 'Hooters Road Trip takes you on a tour of American highways. Drive fast, win challenges, and enjoy the scenery in this unique arcade title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hot-shots-golf', 'Playstation', 'Hot Shots Golf', '1997', 'Sports', 'Camelot Software Planning', '4', 'Golf simulation', '3D golf simulation with a cartoon aesthetic and physics.', 'Win tournaments and unlock new characters and courses.', 'An incredibly fun and accessible golf game for all players.', 'Hot Shots Golf (known as Everybodys Golf) is a PlayStation classic. Master the "three-click" swing system and enjoy charming visuals in this sports hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hot-wheels---extreme-racing', 'Playstation', 'Hot Wheels - Extreme Racing', '2001', 'Racing', 'Black Rock Studio', '2', 'Arcade racing', 'Arcade-style racing with small toy cars and creative tracks.', 'Win races and perform stunts to prove you are the best driver.', 'A fast and flashy racer based on the famous toy brand.', 'Hot Wheels - Extreme Racing features transforming vehicles and loops. Race through house-themed tracks and use power-ups to defeat your rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hot-wheels---turbo-racing', 'Playstation', 'Hot Wheels - Turbo Racing', '1999', 'Racing', 'Climax Studios', '2', 'Arcade racing', 'High-speed stunt racing with weaponized Hot Wheels cars.', 'Collect points through stunts and win high-stakes races.', 'A high-energy racer known for its great soundtrack and speed.', 'Hot Wheels - Turbo Racing delivers pure arcade fun. Master the air-stunts and find hidden short-cuts in this explosive toy racing game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hugo:-the-evil-mirror', 'Playstation', 'Hugo: The Evil Mirror', '2000', 'Adventure', 'Ite Media', '1', 'Action adventure', '2D side-scrolling platformer featuring the mischievous Hugo.', 'Help Hugo save his family by traveling through magical mirrors.', 'A charming adventure with diverse environments and puzzles.', 'Hugo: The Evil Mirror offers classic platforming fun. Use different powers to navigate surreal worlds and defeat the evil witch Scylla.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hyakujuu-sentai-gaoranger', 'Playstation', 'Hyakujuu Sentai Gaoranger', '2001', 'Action', 'Banpresto', '2', 'Sentai action', '3D action game based on the Super Sentai (Power Rangers) series.', 'Defeat the Orgs using the powers of the Gao Warriors and mechs.', 'A high-energy action title with giant robot battles.', 'Hyakujuu Sentai Gaoranger captures the spirit of the show. Fight as your favorite ranger and summon the Gao King to finish off giant monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('hybrid', 'Playstation', 'Hybrid', '1999', 'Shooter', 'Extreme Entertainment Group', '2', 'First-person shooter', '3D fighting game with a focus on aerial combat and projectiles.', 'Defeat all opponents to uncover the secret of the Hybrid project.', 'A unique 3D fighter with a dark and futuristic aesthetic.', 'Hybrid offers a different take on the brawler genre. Use flight and energy attacks to outmaneuver your rivals in this technical and rare fighter.');
