INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iq---intelligent-qube', 'Playstation', 'I.Q - Intelligent Qube', '1997', 'Puzzle', 'Sony Interactive Studios', '2', 'Logic puzzle', 'Spatial logic puzzle game with a minimalist aesthetic.', 'Clear waves of rolling cubes by marking the floor in time.', 'One of the most original and addictive puzzles on the PS1.', 'I.Q - Intelligent Qube (known as Kurushi) is a test of intelligence and speed. Prevent the cubes from crushing you in this hypnotic and challenging game.');
