INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ian-livingstones-deathtrap-dungeon-usa', 'Playstation', 'Ian Livingstone''s Deathtrap Dungeon (USA)', '1998', 'Action', 'Asylum Games', '1', 'Action RPG', 'Third-person hack-and-slash adventure set in a trap-filled dungeon.', 'Survive the trials of the Baron Sukumvit to claim the prize.', 'The North American release of the hardcore fantasy adventure.', 'Ian Livingstone''s Deathtrap Dungeon (USA) delivers brutal combat and complex levels. Master your weapons and watch your step in this fantasy epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ihra-drag-racing', 'Playstation', 'IHRA Drag Racing', '2001', 'Racing', 'Bethesda Softworks', '2', 'Drag racing simulation', 'High-performance drag racing simulation with licensed cars.', 'Win 1/4 mile drag races by mastering tuning and reaction time.', 'A specialized racing sim focused on the IHRA circuit.', 'IHRA Drag Racing offers deep mechanical customization. Fine-tune your engine and time your shifts perfectly to become the drag racing champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('in-the-hunt', 'Playstation', 'In The Hunt', '1997', 'Shooter', 'Irem', '2', 'Side-scrolling shooter', '2D fighting game with unique "Stand" summon mechanics.', 'Defeat Dio Brando and his followers across Egypt.', 'A stylish Capcom fighter based on the Stardust Crusaders arc.', 'JoJo''s Bizarre Adventure features stunning pixel art and intense combat. Master the "Stand" system to unleash devastating supernatural combos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('independence-day', 'Playstation', 'Independence Day', '1996', 'Action', 'Radar Pictures', '1', 'Action adventure', 'Mission-based 3D tank combat simulation.', 'Complete various military objectives using a customizable tank.', 'A tactical and action-heavy tank sim for military fans.', 'Joint Strike Force puts you in command of advanced armored vehicles. Coordinate your strikes and upgrade your tank to dominate the battlefield.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('infestation', 'Playstation', 'Infestation', '2000', 'Strategy', 'Frontier Developments', '1', 'Real-time strategy', '3D platformer featuring a young boy and his magic wand.', 'Journey through a fantasy world to save the kingdom from darkness.', 'A charming and colorful adventure from the makers of Mega Man.', 'Jump Start features a unique "capture and use" mechanic with your wand. Explore vibrant 3D worlds in this lighthearted and creative platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('initial-d', 'Playstation', 'Initial D', '1998', 'Racing', 'Kaneko', '2', 'Arcade street racing', '3D kart racing featuring various Jump Start characters.', 'Win races across educational-themed tracks to earn trophies.', 'A fun and accessible racer designed for younger audiences.', 'Jump Start: Race''n Learn combines speed with basic learning elements. Perfect for kids, it offers simple controls and vibrant, safe environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('inspector-gadget---gadgets-crazy-maze-usa-enfrdeesitnl', 'Playstation', 'Inspector Gadget - Gadget''s Crazy Maze (USA) (En,Fr,De,Es,It,Nl)', '1999', 'Adventure', 'Rebellion Developments', '1', 'Action maze adventure', 'Educational mini-game collection focused on creativity.', 'Solve puzzles and complete artistic tasks to help the characters.', 'A safe and engaging learning tool for preschool-aged children.', 'Jump Start: Wildlife Safari makes education interactive. Explore animal habitats while building foundational skills in this charming family title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('intellivision-classic', 'Playstation', 'Intellivision Classic', '1999', 'Compilation', 'Digital Eclipse', '2', 'Classic game compilation', 'First-person flight combat featuring high-tech starfighters.', 'Defeat the alien invaders and protect the colony in deep space.', 'A fast-paced sci-fi shooter with a cinematic atmosphere.', 'Jupiter Strike offers high-intensity space dogfights. Master your ship''s weapons to survive waves of enemy fighters in this early PS1 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-karate-plus', 'Playstation', 'International Karate Plus', '1996', 'Fighting', 'System 3', '2', 'Martial arts fighting', 'Arcade-style 3D beat ''em up based on the classic manga.', 'Fight through the city to stop a massive criminal organization.', 'A high-energy brawler featuring the voice of the original cast.', 'Junk Fist delivers visceral martial arts action. Choose your fighter and use devastating special moves to clear the streets of thugs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('international-superstar-soccer-pro', 'Playstation', 'International Superstar Soccer Pro', '1997', 'Sports', 'Konami', '4', 'Soccer simulation', '2D platformer/adventure based on the Jurassic Park films.', 'Navigate Isla Sorna and survive encounters with deadly dinosaurs.', 'A tense side-scrolling journey through a prehistoric jungle.', 'Jurassic Park: The Lost World on PS1 lets you play as both hunter and prey. Experience cinematic encounters and survive the T-Rex in this atmospheric title.');
