INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('inuyasha:-a-fairy-feudal-tale', 'Playstation', 'InuYasha: A Fairy Feudal Tale', '2001', 'Fighting', 'Dimps', '2', '3D arena fighting', 'Competitive block-matching puzzle with a fast-paced rhythm.', 'Clear blocks by matching colors to send junk to your opponent.', 'An addictive and colorful puzzle classic from Japan.', 'Justice Gakuen (Rival Schools) Puzzler offers a fun twist on the genre. Enjoy fast gameplay and charming character interactions in this competitive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('invasion-from-beyond', 'Playstation', 'Invasion From Beyond', '1998', 'Horror', 'Imagineer', '1', 'Survival horror', 'Vertical-scrolling "shmup" with a feudal Japanese theme.', 'Blast through yokai and demons to save the ancient kingdom.', 'A beautiful and challenging shooter based on Japanese folklore.', 'Kaitei Daisensou (In the Hunt) features incredible pixel art. Navigate treacherous waters and destroy massive bosses in this legendary shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('iron-soldier-3', 'Playstation', 'Iron Soldier 3', '1997', 'Action', 'Realtime Associates', '1', 'Mech action shooter', '2D side-scrolling action-adventure featuring the "Kamen Rider."', 'Defeat the Shocker organization and their mutated monsters.', 'A nostalgic brawler based on the classic Tokusatsu hero.', 'Kamen Rider brings the legendary masked hero to life. Perform the iconic "Rider Kick" and protect the world from evil in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('irritating-stick', 'Playstation', 'Irritating Stick', '1999', 'Puzzle', 'SCE Japan Studio', '2', 'Physics puzzle', 'High-speed 3D kart racing with weaponized power-ups.', 'Win the championship and unlock new kart upgrades and racers.', 'A fast and accessible arcade racer for all skill levels.', 'Kart Challenge delivers competitive fun on the asphalt. Master the drift and use your items strategically to take the checkered flag.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jackie-chan-stuntmaster', 'Playstation', 'Jackie Chan Stuntmaster', '2000', 'Action', 'Radical Entertainment', '1', 'Platform action', '3D kart racing featuring characters from various Konami games.', 'Win the Konami Cup across tracks inspired by classic titles.', 'A charming crossover racer featuring characters like Goemon.', 'Konami Open Golf offers a different pace with its golf-inspired tracks. Use unique character abilities to outpace your rivals in this fun kart racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeff-waynes---the-war-of-the-worlds', 'Playstation', 'Jeff Wayne''s - The War of the Worlds', '1999', 'Strategy', 'Kuju Entertainment', '1', 'Real-time strategy', 'Professional 3D bowling simulation with realistic physics.', 'Achieve the perfect 300 score and win pro tournaments.', 'A focused and realistic bowling game for fans of the sport.', 'K-1 Grand Prix Bowling brings the lane experience home. Customize your ball and master your hook to become a bowling champion on the PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jeremy-mcgrath-supercross-2000', 'Playstation', 'Jeremy McGrath Supercross 2000', '2000', 'Sports', 'Acclaim Entertainment', '2', 'Motocross racing', 'Combat-focused professional kickboxing simulation.', 'Win the K-1 World Grand Prix by knocking out top-tier fighters.', 'A technical and realistic fighting game based on the K-1 league.', 'K-1 Grand Prix offers an authentic kickboxing experience. Master the timing of your strikes and blocks to conquer the most prestigious ring in the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jersey-devil', 'Playstation', 'Jersey Devil', '1997', 'Platform', 'Behaviour Interactive', '1', '3D platformer', '2D side-scrolling run-and-gun action game.', 'Infiltrate enemy bases and destroy the bio-weapon threat.', 'A high-intensity shooter with a gritty military theme.', 'Killer Loop features fast-paced gunplay and massive bosses. Use a variety of heavy weapons to blast your way through hostile territory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jet-ace', 'Playstation', 'Jet Ace', '1997', 'Shooter', 'Bit Managers', '1', 'Arcade shooter', 'Futuristic high-speed racing on magnetic tracks.', 'Win races and destroy rivals in gravity-defying hover-cars.', 'A stylish and incredibly fast racer with a techno soundtrack.', 'Killer Loop (USA) takes racing to the edge of the galaxy. Master the magnet-grip mechanic to drive on walls and ceilings in this intense sci-fi hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jet-moto-2', 'Playstation', 'Jet Moto 2', '1997', 'Racing', '989 Studios', '2', 'Hover bike racing', 'High-energy soccer simulation with the 2000 season data.', 'Win the J-League and lead your club to national glory.', 'The definitive Japanese soccer experience for the year 2000.', 'Konami J-League 2000 features updated rosters and refined AI. Experience the passion of Japanese football with polished mechanics and realistic atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-oshaberi-parodius---forever-with-me-japan', 'Playstation', 'Jikkyou Oshaberi Parodius - Forever with Me (Japan)', '1998', 'Shooter', 'Konami', '2', 'Parody shoot ''em up', 'Traditional 2D puzzle game featuring the "Koro Koro" mechanics.', 'Navigate the ball through mazes by tilting the world.', 'A physics-based puzzler that requires precision and timing.', 'Koro Koro Postman offers a unique and charming challenge. Deliver mail safely through trap-filled levels in this addictive and cute puzzle title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu---premium-ban', 'Playstation', 'Jikkyou Powerful Pro Yakyuu - Premium-ban', '1995', 'Sports', 'Konami', '2', 'Baseball simulation', 'Educational and creative software featuring the Kouen character.', 'Complete various mini-games and puzzles to learn new skills.', 'A gentle and interactive learning game for younger kids.', 'Kouen: The Little Guardian makes learning fun. Explore a colorful world and solve simple logic puzzles in this family-oriented digital adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-95', 'Playstation', 'Jikkyou Powerful Pro Yakyuu ''95', '1995', 'Sports', 'Konami', '2', 'Baseball simulation', '2D fighting game featuring a diverse and bizarre cast.', 'Win the tournament to claim the ultimate fighting title.', 'A fast-paced and technical brawler with a unique aesthetic.', 'Kyuiin (The Vaccuum) offers a strange and wonderful fighting experience. Master the unique character moves and dominate the arena in this rare Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-95---kaimakuban', 'Playstation', 'Jikkyou Powerful Pro Yakyuu ''95 - Kaimakuban', '1995', 'Sports', 'Konami', '2', 'Baseball simulation', 'High-speed motorcycle racing focusing on realism and tuning.', 'Win the superbike championship and unlock new bikes.', 'A professional racing sim for motorcycle enthusiasts.', 'Kawasaki Superbike Challenge delivers authentic bike physics. Master the corners and manage your speed to take the lead in this licensed racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-97---kaimakuban', 'Playstation', 'Jikkyou Powerful Pro Yakyuu ''97 - Kaimakuban', '1997', 'Sports', 'Konami', '2', 'Baseball simulation', 'Competitive billiards simulation with 3D graphics.', 'Clear the table and defeat opponents in various pool games.', 'A solid and accessible billiards title for the PS1.', 'Kay''s Billiards offers a variety of modes and realistic ball movement. Perfect your shots and climb the rankings in this sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-98---kaimakuban', 'Playstation', 'Jikkyou Powerful Pro Yakyuu ''98 - Kaimakuban', '1998', 'Sports', 'Konami', '2', 'Baseball simulation', 'High-octane arcade racing with destructive elements.', 'Win races by any means necessary, including smashing rivals.', 'A fast and aggressive racer that rewards high-risk driving.', 'Kileak: The Blood delivers intense arcade racing thrills. Navigate through hazardous tracks and leave your opponents in the dust.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-98---ketteiban', 'Playstation', 'Jikkyou Powerful Pro Yakyuu ''98 - Ketteiban', '1998', 'Sports', 'Konami', '2', 'Baseball simulation', 'First-person shooter with mecha-combat and exploration.', 'Infiltrate a high-tech facility to stop a biological outbreak.', 'A dark and atmospheric mecha-FPS with a sci-fi theme.', 'Kileak: The DNA Imperative puts you in the pilot seat of a powerful exoskeleton. Battle through futuristic hallways and solve mysteries in this early PS1 hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-99---kaimakuban-japan', 'Playstation', 'Jikkyou Powerful Pro Yakyuu ''99 - Kaimakuban (Japan)', '1999', 'Sports', 'Konami', '2', 'Baseball simulation', 'First-person shooter/mecha sequel with improved visuals and speed.', 'Neutralize a new threat in an expanded industrial complex.', 'An explosive follow-up to the original mecha-combat game.', 'Kileak 2: Blood on the Moon ramps up the action with new weapons and enemies. Survive the mechanical onslaught in this sci-fi shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-99---ketteiban', 'Playstation', 'Jikkyou Powerful Pro Yakyuu ''99 - Ketteiban', '1999', 'Sports', 'Konami', '2', 'Baseball simulation', 'Rhythm-based dancing game featuring disco and pop hits.', 'Match the on-screen prompts to keep the dance floor moving.', 'A vibrant and groovy rhythm game for party fans.', 'King of Bowling 2 features flashy moves and a fun soundtrack. Master the rhythm and become the star of the club in this rhythmic hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-2000---kaimakuban', 'Playstation', 'Jikkyou Powerful Pro Yakyuu 2000 - Kaimakuban', '2000', 'Sports', 'Konami', '2', 'Baseball simulation', '3D weapon-based fighting game with cinematic camera angles.', 'Defeat a roster of supernatural rivals to claim victory.', 'A unique fighter known for its "TV broadcast" style presentation.', 'King of Fighters ''95 brings the SNK legend to the 32-bit era. Experience fast-paced team battles and iconic special moves on the PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-2000---ketteiban', 'Playstation', 'Jikkyou Powerful Pro Yakyuu 2000 - Ketteiban', '2000', 'Sports', 'Konami', '2', 'Baseball simulation', 'Traditional 2D fighting game with massive character rosters.', 'Win the annual fighting tournament as a team of three.', 'One of the most famous and technical fighting series in history.', 'King of Fighters ''96 features refined mechanics and beautiful sprite art. Master the "Max" system and unleash devastating combos in this arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-2001', 'Playstation', 'Jikkyou Powerful Pro Yakyuu 2001', '2001', 'Sports', 'Konami', '2', 'Baseball simulation', '2D team-based fighting with a focus on tactical play.', 'Defeat rival teams to prove your group is the world''s strongest.', 'An improved sequel with deeper mechanics and more characters.', 'King of Fighters ''97 delivers the conclusion of the Orochi saga. Choose your favorite trio and master the unique "Advanced" and "Extra" modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-2001---ketteiban', 'Playstation', 'Jikkyou Powerful Pro Yakyuu 2001 - Ketteiban', '2001', 'Sports', 'Konami', '2', 'Baseball simulation', '2D team-based fighting game featuring the debut of K''.', 'Stop the NESTS organization and win the global tournament.', 'A stylish evolution of the series with a darker aesthetic.', 'King of Fighters ''99 features the new "Striker" system. Build a team of four and dominate the competition in this high-energy fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jikkyou-powerful-pro-yakyuu-2002---haru', 'Playstation', 'Jikkyou Powerful Pro Yakyuu 2002 - Haru', '2002', 'Sports', 'Konami', '2', 'Baseball simulation', 'First-person action-RPG with a focus on atmosphere and mystery.', 'Navigate a dark island to recover the legendary Moonlight Sword.', 'A haunting and difficult dungeon-crawler from FromSoftware.', 'King''s Field is the spiritual ancestor to the Souls series. Experience slow, methodical exploration and tense combat in this atmospheric RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jim-hensons-bear-in-the-big-blue-house', 'Playstation', 'Jim Henson''s Bear in the Big Blue House', '2001', 'Edutainment', 'Brøderbund', '1', 'Children''s adventure', 'First-person action-RPG sequel with a larger world and more lore.', 'Explore a vast kingdom and defeat ancient evil forces.', 'A deep and challenging RPG that rewards careful exploration.', 'King''s Field II (US) expands on the original''s formula with better graphics and more complex dungeons. A must-play for fans of dark fantasy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jimmy-whites-2:-cueball', 'Playstation', 'Jimmy White''s 2: Cueball', '1996', 'Sports', 'Awesome Developments', '2', 'Pool simulation', '3D action-adventure featuring a young fox knight.', 'Solve puzzles and fight enemies to save the kingdom of The Hub.', 'A charming and colorful adventure in the vein of Zelda.', 'Kingsley''s Adventure offers vibrant 3D worlds and engaging combat. Use your sword and magic to overcome challenges in this family-friendly quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jinx', 'Playstation', 'Jinx', '1997', 'Platformer', 'Psygnosis', '1', '3D platformer', '3D platformer featuring a court jester with magic abilities.', 'Save the world of Ploog from an evil spell and rescue the royal family.', 'A colorful and quirky platformer with a magical twist.', 'Jinx puts you in the shoes of a heroic jester. Master magical spells and navigate vibrant 3D worlds to stop a dark wizard in this family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('johnny-bazookatone', 'Playstation', 'Johnny Bazookatone', '1996', 'Platformer', 'Arc Developments', '1', '3D platformer', '2.5D side-scrolling platformer with a musical combat theme.', 'Use your guitar-gun to blast through the underworld and rescue souls.', 'A stylish action-platformer featuring a rock-star hero.', 'Johnny Bazookatone delivers high-energy shooting and platforming. Blast your way through bizarre levels with your "Anita" guitar in this rhythmic cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jojos-bizarre-adventure', 'Playstation', 'Jojo''s Bizarre Adventure', '1998', 'Fighting', 'Capcom', '2', '2D fighting', '2D fighting game with unique "Stand" summon mechanics.', 'Defeat Dio Brando and his followers across Egypt.', 'A stylish Capcom fighter based on the Stardust Crusaders arc.', 'JoJo''s Bizarre Adventure features stunning pixel art and intense combat. Master the "Stand" system to unleash devastating supernatural combos on PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('judge-dredd', 'Playstation', 'Judge Dredd', '1998', 'Action', 'Gremlin Interactive', '1', 'Action shooter', 'Third-person shooter/action game set in a dystopian future.', 'Arrest or execute criminals to restore order in Mega-City One.', 'A gritty action game based on the iconic comic book hero.', 'Judge Dredd: I Am The Law brings the law to the streets. Use a variety of specialized ammunition to take down the scum of the city in this intense shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jumping-flash!-europe', 'Playstation', 'Jumping Flash! (Europe)', '1995', 'Platformer', 'Exact', '1', 'First-person platformer', 'First-person 3D platformer featuring a robotic rabbit.', 'Leap through floating worlds to stop Baron Aloha''s galactic plans.', 'A revolutionary 3D platformer known for its massive vertical jumps.', 'Jumping Flash! (Europe) offers a unique perspective on platforming. Experience the thrill of triple-jumping through colorful, open-air 3D stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jumping-flash!-2---big-trouble-in-little-muu-europe', 'Playstation', 'Jumping Flash! 2 - Big Trouble in Little Muu (Europe)', '1996', 'Platformer', 'Exact', '1', 'First-person platformer', 'First-person 3D platformer with expanded worlds and mechanics.', 'Capture the Muu-Muu creatures and defeat the giant invader, Capitán Kabuki.', 'The enhanced sequel to the world''s first first-person platformer.', 'Jumping Flash! 2 - Big Trouble in Little Muu delivers larger levels and more secrets. Pilot the robotic rabbit Robbit to save the galaxy once again.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jumpstart-wildlife-safari---field-trip', 'Playstation', 'JumpStart Wildlife Safari - Field Trip', '1999', 'Educational', 'Knowledge Adventure', '1', 'Educational exploration', 'Educational mini-game collection focused on wildlife.', 'Solve nature-based puzzles and learn about various animal species.', 'An engaging and educational field trip for younger players.', 'JumpStart Wildlife Safari - Field Trip makes learning about nature fun. Participate in interactive activities to discover the wonders of the animal kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('jupiter-strike', 'Playstation', 'Jupiter Strike', '1996', 'Shooter', 'Taito', '2', 'Arcade space shooter', 'First-person flight combat featuring high-tech starfighters.', 'Defeat the alien invaders and protect the colony in deep space.', 'A fast-paced sci-fi shooter with a cinematic atmosphere.', 'Jupiter Strike offers high-intensity space dogfights. Master your ship''s weapons to survive waves of enemy fighters in this early PS1 classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('k95-2---we-are-the-dogs!', 'Playstation', 'K9.5 2 - We Are the Dogs!', '2000', 'Educational', 'Mattel Interactive', '1', 'Children''s adventure', 'Musical educational game featuring anthropomorphic dogs.', 'Participate in rhythmic challenges and learn musical basics.', 'A fun and interactive musical game for children.', 'K9.5 2 - We Are the Dogs! combines music education with playful characters. Engage in sing-alongs and rhythmic games designed for young learners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('k95-3---webtunes', 'Playstation', 'K9.5 3 - Webtunes', '2001', 'Educational', 'Mattel Interactive', '1', 'Children''s adventure', 'Educational software focused on internet and web concepts.', 'Explore the "Webtunes" world to learn about digital connectivity.', 'A tech-themed educational tool for children.', 'K9.5 3 - Webtunes introduces kids to the digital age. Learn about communication and technology through fun, dog-themed activities and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('k95-4---the-tail-wag-tour', 'Playstation', 'K9.5 4 - The Tail-Wag Tour', '2001', 'Educational', 'Mattel Interactive', '1', 'Children''s adventure', 'Interactive musical adventure and educational software.', 'Join the dogs on a tour to learn about geography and culture.', 'A globetrotting educational journey for kids.', 'K9.5 4 - The Tail-Wag Tour offers music and lessons from around the world. Discover new places and cultures with the K9.5 crew in this fun title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kaettekita-cyborg-kuro-chan', 'Playstation', 'Kaettekita Cyborg Kuro-chan', '2000', 'Action', 'Konami', '1', 'Action platformer', '2D side-scrolling run-and-gun based on the anime.', 'Fight through robot hordes as a heavily armed cyborg cat.', 'A chaotic and explosive action game for fans of the series.', 'Kaettekita Cyborg Kuro-chan features non-stop shooting and destruction. Customize your cat-bot and blast through urban levels in this high-energy brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kagero---deception-ii-usa', 'Playstation', 'Kagero - Deception II (USA)', '1998', 'Strategy', 'Tecmo', '1', 'Trap-based strategy', 'Tactical trap-setting game with a dark narrative.', 'Defend your castle from invaders by placing lethal traps.', 'A unique strategy-horror hybrid and sequel to Tecmo''s Deception.', 'Kagero - Deception II (USA) is a game of strategic cruelty. Create chain-reactions of traps to eliminate enemies in this deep psychological thriller.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakuge-yaro', 'Playstation', 'Kakuge Yaro', '1996', 'Fighting', 'Raizing', '2', 'Arcade fighting', '2D fighting game featuring various martial arts styles.', 'Win the tournament to prove you are the ultimate brawler.', 'A classic Japanese fighter with a focus on technical combos.', 'Kakuge Yaro offers competitive 2D combat. Choose your fighter and master unique special moves to dominate your opponents in the arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakuge-yarou---fighting-game-creator-japan', 'Playstation', 'Kakuge Yarou - Fighting Game Creator (Japan)', '1996', 'Fighting', 'Media Entertainment', '2', 'Fighting game editor', 'Fighting game creation tool with 2D combat mechanics.', 'Design your own characters and movesets to build a custom fighter.', 'A unique "sandbox" tool for creating fighting games.', 'Kakuge Yarou - Fighting Game Creator lets you become a developer. Design animations and balance your own brawlers in this innovative creative suite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakuge-yarou---fighting-game-creator-japan-en-by-transgen-v10beta', 'Playstation', 'Kakuge Yarou - Fighting Game Creator (Japan) [En by TransGen v1.0Beta]', '1996', 'Fighting', 'Media Entertainment', '2', 'Fighting game editor', 'Translated fighting game creation tool.', 'Design your own characters and movesets in English.', 'The English fan-translation of the famous fighter creation tool.', 'Kakuge Yarou [En by TransGen] makes the complex creation tools accessible to Western fans. Build the ultimate 2D fighter with ease.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kakugo-no-susume', 'Playstation', 'Kakugo No Susume', '1995', 'Action', 'Takara', '2', 'Beat ''em up', '2D fighting game based on the violent manga series.', 'Fight through a post-apocalyptic world to defeat your rivals.', 'A gritty and technical fighter with a unique artistic style.', 'Kakugo No Susume (Apocalypse Zero) features brutal combat and specialized armor suits. Experience the intensity of the manga in this 32-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider', 'Playstation', 'Kamen Rider', '1997', 'Action', 'Bottom Up', '1', 'Action adventure', '2D side-scrolling action based on the Tokusatsu hero.', 'Fight through Shocker agents to protect humanity.', 'A nostalgic brawler starring the legendary masked hero.', 'Kamen Rider brings the classic TV action to life. Use iconic "Rider Kicks" and combat skills to defeat mutated monsters in this action hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider-agito', 'Playstation', 'Kamen Rider Agito', '2001', 'Action', 'Bottom Up', '1', 'Action adventure', '3D fighting game based on the Agito TV series.', 'Battle as different riders to stop the mysterious "Unknown" threat.', 'A polished 3D fighter featuring high-quality models and effects.', 'Kamen Rider Agito lets you play as Agito, G3, and Gills. Experience the power of the Henshin heroes in intense one-on-one arena battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider-kuuga', 'Playstation', 'Kamen Rider Kuuga', '2000', 'Action', 'Bottom Up', '1', 'Action adventure', '3D fighting game featuring the many forms of Kuuga.', 'Fight the Grongi tribe to protect the smiles of the innocent.', 'A technical 3D fighter with form-changing mechanics.', 'Kamen Rider Kuuga captures the essence of the show. Master Kuuga''s different forms and finishing moves in this high-energy fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider-ryuki', 'Playstation', 'Kamen Rider Ryuki', '2002', 'Action', 'Bottom Up', '1', 'Action adventure', 'Card-based 3D fighting game with summoning mechanics.', 'Win the Rider War by defeating other Riders in the Mirror World.', 'A strategic brawler based on the Ryuki TV series.', 'Kamen Rider Ryuki features unique card-contract mechanics. Summon "Mirror Monsters" to assist you in battle in this technical 3D fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider-v3', 'Playstation', 'Kamen Rider V3', '1995', 'Action', 'Natsume', '1', 'Action adventure', '2D side-scrolling brawler based on the classic V3 series.', 'Stop the Destron organization across various action-packed levels.', 'A retro-style action game for fans of classic Tokusatsu.', 'Kamen Rider V3 brings the third rider to center stage. Fight iconic villains and use specialized vehicles in this nostalgic action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kamen-rider:-the-bike-race', 'Playstation', 'Kamen Rider: The Bike Race', '1998', 'Racing', 'Takara', '1', 'Motorcycle racing', '3D motorcycle racing game featuring Kamen Rider characters.', 'Win high-speed races and use combat moves to defeat other riders.', 'A unique mix of bike racing and Rider combat.', 'Kamen Rider: The Bike Race combines speed with signature hero moves. Outrun and outfight your rivals to be the first across the finish line.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kattobi-tune', 'Playstation', 'Kattobi Tune', '1996', 'Racing', 'Z-Axis', '2', 'Arcade racing', 'High-speed illegal street racing in Japanese urban environments.', 'Build your reputation and win underground races to upgrade your car.', 'A gritty and atmospheric Japanese racing title.', 'Kattobi Tune focuses on the Japanese tuning culture. Master drifting and high-speed highway runs in this niche and stylish racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('keio-flying-squadron', 'Playstation', 'Keio Flying Squadron', '1994', 'Shooter', 'Victor Entertainment', '1', 'Horizontal shooter', '2D side-scrolling shooter with a magical-girl theme.', 'Fly through surreal levels and defeat weird bosses to save the kingdom.', 'A beautiful and quirky "shmup" with a unique visual style.', 'Keio Flying Squadron features charming animation and challenging shooting. Help Rami and her pet dragon save the world in this colorful shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kensei:-sacred-fist', 'Playstation', 'Kensei: Sacred Fist', '1998', 'Fighting', 'Konami', '2', '3D fighting', '3D fighting game with a focus on realistic martial arts.', 'Defeat a diverse roster of fighters in global arenas.', 'A technical 3D brawler from Konami with smooth animations.', 'Kensei: Sacred Fist offers a grounded approach to fighting. Master realistic movesets and counters in this polished martial arts simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kickboxing', 'Playstation', 'Kickboxing', '1997', 'Sports', 'Taito', '2', 'Boxing simulation', 'Professional 3D kickboxing simulation with realistic physics.', 'Climb the ranks and win the world kickboxing title.', 'A technical sports game focused on precision and timing.', 'Kickboxing for PS1 offers an authentic ring experience. Manage your stamina and land perfect strikes to knock out your opponents in this sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kids-station---bishoujo-senshi-sailor-moon-world---chibiusa-to-tanoshii-mainichi-japan', 'Playstation', 'Kids Station - Bishoujo Senshi Sailor Moon World - Chibiusa to Tanoshii Mainichi (Japan)', '1995', 'Educational', 'Bandai', '1', 'Children''s adventure', 'Educational mini-games featuring the Sailor Moon cast.', 'Solve simple puzzles and learn basic skills with Chibiusa.', 'A gentle and interactive game for young fans of the series.', 'Sailor Moon World - Chibiusa to Tanoshii Mainichi makes learning magical. Enjoy safe and colorful activities designed for early childhood development.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kids-station---doraemon---himitsu-no-yojigen-pocket-japan-controller-set', 'Playstation', 'Kids Station - Doraemon - Himitsu no Yojigen Pocket (Japan) (Controller Set)', '1996', 'Educational', 'Bandai', '1', 'Children''s adventure', 'Educational activities featuring Doraemon and his gadgets.', 'Explore the 4D pocket and play games with Nobita and Doraemon.', 'A fun and interactive learning experience for children.', 'Doraemon - Himitsu no Yojigen Pocket uses the iconic series to teach logic and creativity. Perfect for young learners and fans of the robot cat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kileak:-the-dna', 'Playstation', 'Kileak: The DNA', '1995', 'Shooter', 'Gensho Interactive', '1', 'Survival horror shooter', 'First-person shooter with mecha-combat and exploration.', 'Infiltrate a high-tech facility to stop a biological outbreak.', 'A dark and atmospheric mecha-FPS with a sci-fi theme.', 'Kileak: The DNA Imperative puts you in the pilot seat of a powerful exoskeleton. Battle through futuristic hallways and solve mysteries in this early PS1 hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killer-loop', 'Playstation', 'Killer Loop', '1997', 'Racing', 'Bionx', '2', 'Futuristic racing', 'Futuristic high-speed racing on magnetic tracks.', 'Win races and destroy rivals in gravity-defying hover-cars.', 'A stylish and incredibly fast racer with a techno soundtrack.', 'Killer Loop features intense 32-bit racing. Master the magnet-grip mechanic to drive on walls and ceilings in this high-octane sci-fi competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killing-time-usa-beta', 'Playstation', 'Killing Time (USA) (Beta)', '1995', 'Shooter', 'Studio 3DO', '1', 'First-person shooter', 'First-person shooter/adventure set in an Egyptian tomb.', 'Survive the supernatural traps and horrors of a cursed pharaoh.', 'A rare beta version of the high-energy FPS/Horror hybrid.', 'Killing Time (Beta) offers a look at the development of this atmospheric shooter. Battle undead threats in a pre-release version of this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('killing-zone', 'Playstation', 'Killing Zone', '1996', 'Fighting', '3DO Company', '2', '3D fighting', '3D arena-based fighting game with fantasy characters.', 'Defeat rivals in one-on-one combat to claim ultimate power.', 'A technical 3D fighter with a focus on weapons and magic.', 'Killing Zone features diverse characters and high-stakes combat. Master the unique abilities of each fighter to dominate the arena in this 3D brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('king-of-fighters-95-the-usa', 'Playstation', 'King of Fighters ''95, The (USA)', '1995', 'Fighting', 'SNK', '2', '2D fighting', '2D weapon-based fighting game with cinematic camera angles.', 'Defeat a roster of supernatural rivals to claim victory.', 'A unique fighter known for its "TV broadcast" style presentation.', 'The King of Fighters ''95 brings the SNK legend to the 32-bit era. Experience fast-paced team battles and iconic special moves on the PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-field', 'Playstation', 'King''s Field', '1994', 'RPG', 'FromSoftware', '1', 'First-person RPG', 'First-person action-RPG with a focus on atmosphere and mystery.', 'Navigate a dark island to recover the legendary Moonlight Sword.', 'A haunting and difficult dungeon-crawler from FromSoftware.', 'King''s Field is the spiritual ancestor to the Souls series. Experience slow, methodical exploration and tense combat in this atmospheric RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-field-ii', 'Playstation', 'King''s Field II', '1995', 'RPG', 'FromSoftware', '1', 'First-person RPG', 'First-person action-RPG with a focus on dark atmosphere.', 'Recover the Moonlight Sword and survive the island of Melanat.', 'A punishing and immersive cult-classic dungeon crawler.', 'King''s Field II (released as King''s Field in the West) is a pioneer of the first-person RPG genre. Explore a seamless, trap-filled world with deep lore and methodical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kings-field-iii---pilot-style-english-patched', 'Playstation', 'King''s Field III - Pilot Style (English Patched)', '1996', 'RPG', 'FromSoftware', '1', 'First-person RPG', 'First-person action-RPG demo/side story with a translation.', 'Explore a vertical dungeon and master magic in this prologue.', 'The English-patched "Pilot Style" version of the third entry.', 'King''s Field III - Pilot Style offers a unique look at the world of Verdite. This translated version provides a tactical and atmospheric dungeon-crawling experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kingsleys-adventure', 'Playstation', 'Kingsley''s Adventure', '1999', 'Platformer', 'Sony Computer Entertainment', '1', '3D platformer', '3D action-adventure with a young fox knight.', 'Solve puzzles and fight enemies to save the kingdom of The Hub.', 'A charming and colorful adventure in the vein of Zelda.', 'Kingsley''s Adventure offers vibrant 3D worlds and engaging combat. Use your sword and magic to overcome challenges in this family-friendly quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kiss-pinball', 'Playstation', 'KISS Pinball', '1998', 'Pinball', 'Digital Illusions CE', '4', 'Arcade pinball', '2D pinball simulation featuring the rock band KISS.', 'Score points and complete missions based on the band''s career.', 'A high-energy pinball game with heavy metal aesthetics.', 'KISS Pinball features two massive tables: "Last Stop: Oblivion" and "Netherworld." Master the flippers to the sound of rock and roll in this arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kitchen-panic', 'Playstation', 'Kitchen Panic', '1994', 'Puzzle', 'Success', '1', 'Arcade puzzle', 'Side-scrolling platformer with a focus on fast movement.', 'Guide a young chef through kitchen-themed levels to reach the goal.', 'A quirky and vibrant Japanese platformer with a food theme.', 'Kitchen Panic offers frantic action and colorful 2D sprites. Use your speed and unique abilities to overcome hazardous kitchen obstacles in this hidden gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klonoa---door-to-phantomile', 'Playstation', 'Klonoa - Door to Phantomile', '1997', 'Platformer', 'Namco', '1', '2.5D platformer', '2.5D side-scrolling platformer with innovative grab mechanics.', 'Defeat Ghadius and save the dream world of Phantomile.', 'A visually stunning and emotional cinematic platformer.', 'Klonoa - Door to Phantomile is a masterpiece of the genre. Use the "Wind Bullet" to toss enemies and navigate beautifully rendered 2.5D landscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klonoa-beach-volley---saikyou-team-kettei-sen!-japan', 'Playstation', 'Klonoa Beach Volley - Saikyou Team Kettei-sen! (Japan)', '2002', 'Sports', 'Namco', '4', 'Arcade beach volleyball', '2-on-2 beach volleyball featuring the Klonoa cast.', 'Win the volleyball tournament by mastering special moves and spikes.', 'The original Japanese version of Klonoa''s sports spin-off.', 'Klonoa Beach Volley features high-energy sports action with a magical twist. Compete with your favorite characters in vibrant, seaside arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('klonoa-beach-volleyball-europe-enfrdeesit', 'Playstation', 'Klonoa Beach Volleyball (Europe) (En,Fr,De,Es,It)', '2002', 'Sports', 'Namco', '4', 'Arcade beach volleyball', '2-on-2 beach volleyball featuring the Klonoa cast.', 'Win the volleyball tournament by mastering special moves and spikes.', 'The multi-language European release of the Klonoa sports title.', 'Klonoa Beach Volleyball brings arcade-style sports to the PS1. Master technical serves and unique character specials in this charming multiplayer game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('knockout-kings', 'Playstation', 'Knockout Kings', '1998', 'Sports', 'EA Canada', '2', 'Boxing simulation', 'Realistic 3D boxing simulation featuring professional fighters.', 'Climb the ranks and win the World Heavyweight Championship.', 'A technical and hard-hitting boxing sim with licensed legends.', 'Knockout Kings delivers authentic ring action. Fight as or against legends like Muhammad Ali and Sugar Ray Leonard in this premier boxing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('konami-arcade-classics', 'Playstation', 'Konami Arcade Classics', '1996', 'Compilation', 'Konami', '2', 'Arcade compilation', 'Compilation of classic Konami arcade titles from the 80s.', 'Achieve high scores in foundational video game classics.', 'Ten legendary arcade ports including Frogger and Gradius.', 'Konami Arcade Classics brings the golden age of arcades home. Experience authentic ports of Scramble, Time Pilot, and more in one package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('korokoro-post-nin', 'Playstation', 'Korokoro Post Nin', '1997', 'Puzzle', 'Hudson Soft', '1', 'Arcade puzzle', '2D puzzle game involving tile manipulation.', 'Deliver mail by navigating complex mazes and matching colors.', 'A charming and unique "postman" themed puzzle challenge.', 'Korokoro Post Nin features addictive gameplay and traditional Japanese aesthetics. Master the spatial puzzles to ensure every letter reaches its home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koudelka-usa-disc-1', 'Playstation', 'Koudelka (USA) (Disc 1)', '1999', 'RPG', 'Sacnoth', '1', 'Horror RPG', 'Turn-based RPG with survival horror elements and exploration.', 'Uncover the dark secrets of Nemeton Monastery in 1898.', 'A gothic horror RPG with cinematic FMV and tactical combat.', 'Koudelka (Disc 1) begins a tragic tale of mystery. Experience a unique blend of "Resident Evil" atmosphere and grid-based RPG battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koudelka-usa-disc-2', 'Playstation', 'Koudelka (USA) (Disc 2)', '1999', 'RPG', 'Sacnoth', '1', 'Horror RPG', 'Turn-based RPG with survival horror elements and exploration.', 'Survive the supernatural terrors deep within the monastery.', 'The second chapter of the dark and atmospheric gothic saga.', 'Koudelka (Disc 2) takes the struggle deeper into the monastery. Master the weapons and magic systems as the narrative tension rises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koudelka-usa-disc-3', 'Playstation', 'Koudelka (USA) (Disc 3)', '1999', 'RPG', 'Sacnoth', '1', 'Horror RPG', 'Turn-based RPG with survival horror elements and exploration.', 'Explore the history of the monastery and face powerful bosses.', 'The intense third act of the supernatural Victorian horror.', 'Koudelka (Disc 3) features pivotal plot developments and challenging tactical encounters in a world of shadows and demons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('koudelka-usa-disc-4', 'Playstation', 'Koudelka (USA) (Disc 4)', '1999', 'RPG', 'Sacnoth', '1', 'Horror RPG', 'Turn-based RPG with survival horror elements and exploration.', 'Reach the final confrontation and discover the monastery''s fate.', 'The dramatic conclusion to the four-disc horror epic.', 'Koudelka (Disc 4) leads to the ultimate battle against the darkness. Witness the cinematic finale of this landmark RPG/Horror hybrid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('krazy-ivan', 'Playstation', 'Krazy Ivan', '1996', 'Action', 'Krisalis Software', '1', 'Action shooter', '3D mech combat with a top-down and third-person perspective.', 'Defeat the cyborg armies across global battlefields.', 'An explosive and high-energy mecha-combat game.', 'Krazy Ivan features massive FMV segments and frantic shooting. Pilot your armored walker and blast through waves of enemies in this arcade-style hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuru-kuru-cube', 'Playstation', 'Kuru Kuru Cube', '1997', 'Puzzle', 'Artdink', '2', 'Arcade puzzle', 'Falling block puzzle game with a unique 3D cube twist.', 'Match colored blocks to clear them from the rotating grid.', 'A stylish and addictive Japanese action-puzzle game.', 'Kuru Kuru Cube challenges your spatial logic and speed. Rotate the cubes and plan your combos in this vibrant and fast-paced puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kuru-kuru-panic', 'Playstation', 'Kuru Kuru Panic', '1997', 'Puzzle', 'Artdink', '2', 'Arcade puzzle', 'Fast-paced 2D action-puzzle game featuring colorful characters.', 'Clear the screen of blocks by matching and spinning icons.', 'A quirky and competitive Japanese puzzle title from Success.', 'Kuru Kuru Panic offers high-speed puzzle gameplay. Master the spinning mechanics to outscore opponents in this hidden 32-bit gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('kurushi-final:-mental-blocks', 'Playstation', 'Kurushi Final: Mental Blocks', '1999', 'Puzzle', 'SIE Japan Studio', '1', 'Logic puzzle', 'Spatial logic puzzle game with a minimalist aesthetic.', 'Clear waves of rolling cubes by marking the floor in time.', 'The expanded and final version of the "Intelligent Qube" series.', 'Kurushi Final: Mental Blocks is the ultimate test of intelligence. Master the advanced modes and survival challenges in this hypnotic puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('largo-winch---commando-sar', 'Playstation', 'Largo Winch - Commando SAR', '2002', 'Action', 'Planet Interactive', '1', 'Action adventure', 'Third-person action-adventure with a focus on stealth and combat.', 'Solve a global conspiracy and survive deadly jungle missions.', 'A cinematic action game based on the popular Belgian comic.', 'Largo Winch - Commando SAR combines infiltration with high-stakes shooting. Navigate complex environments and use gadgets to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lattice-200ec7', 'Playstation', 'Lattice 200EC7', '1998', 'Simulation', 'Mitsui Zosen System Research', '1', 'Mecha simulation', 'Abstract puzzle game with a 3D wireframe aesthetic.', 'Manipulate geometric lattices to clear patterns and score points.', 'A visually unique and minimalist 3D puzzle experience.', 'Lattice 200EC7 offers a hypnotic and challenging take on the puzzle genre. Test your perception and timing in this rare and artistic title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legacy-of-kain---soul-reaver', 'Playstation', 'Legacy of Kain - Soul Reaver', '1999', 'Action', 'Crystal Dynamics', '1', 'Action adventure', 'Third-person action-adventure with gothic horror themes.', 'Reclaim your soul and take revenge on the vampire lord, Kain.', 'A masterpiece of storytelling with a seamless open world.', 'Soul Reaver features an innovative plane-shifting mechanic. Explore the decaying world of Nosgoth as Raziel in this voice-acted epic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-legaia-usa', 'Playstation', 'Legend of Legaia (USA)', '1998', 'RPG', 'Prokion', '1', 'Turn-based RPG', 'Turn-based JRPG featuring a unique martial arts combat system.', 'Use the power of "Ra-Seru" to clear the Mist and save the world.', 'A beloved RPG known for its "Tactical Arts" battle system.', 'Legend of Legaia offers a deep and rewarding combat experience. Master complex button-combos to unleash powerful attacks and save humanity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('legend-of-mana-usa', 'Playstation', 'Legend of Mana (USA)', '1999', 'RPG', 'Square', '1', 'Action RPG', 'Action-RPG with high-quality 2D art and a non-linear story.', 'Restore the world by placing magical artifacts on the map.', 'A stunningly beautiful and artistic entry in the Mana series.', 'Legend of Mana features a unique "Land Make" system. Create your own world and experience diverse, hand-drawn adventures in this Square classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-island-2---the-bricksters-revenge', 'Playstation', 'LEGO Island 2 - The Brickster''s Revenge', '2001', 'Adventure', 'Lego Media', '1', 'Action adventure', '3D platformer with exploration and vehicle missions.', 'Catch the Brickster and restore order to LEGO Island.', 'A diverse and humorous adventure based on the toy brand.', 'LEGO Island 2 features mini-games, puzzles, and exploration. Travel through different Lego themes, from medieval to space, in this fun sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-racers', 'Playstation', 'Lego Racers', '1999', 'Racing', 'High Voltage Software', '4', 'Arcade racing', '3D kart racing with customizable Lego vehicles.', 'Defeat the champion Rocket Racer to become the best in the galaxy.', 'A creative racer that lets you build your own cars and drivers.', 'Lego Racers brings the creativity of bricks to the track. Collect power-ups and build the ultimate racing machine in this colorful arcade hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lego-rock-raiders', 'Playstation', 'Lego Rock Raiders', '2000', 'Strategy', 'Data Design Interactive', '1', 'Real-time strategy', 'Real-time strategy and management with Lego miners.', 'Collect Energy Crystals and survive the dangers of an alien planet.', 'A strategic and atmospheric game based on the Rock Raiders theme.', 'Lego Rock Raiders challenges you to manage a base and explore deep caves. Protect your miners from rock monsters in this unique strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lemmings-&-oh-no!-more-lemmings-usa', 'Playstation', 'Lemmings & Oh No! More Lemmings (USA)', '1994', 'Puzzle', 'DMA Design', '2', 'Puzzle platformer', 'Classic puzzle game featuring the iconic Lemmings and expansion.', 'Guide a group of mindless lemmings safely to the exit of each level.', 'A massive collection featuring the original game and its sequel.', 'Lemmings & Oh No! More Lemmings offers hundreds of challenging puzzles. Use specialized skills to navigate treacherous terrain in this logic classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lightning-legend:-daigo-no-daibouken', 'Playstation', 'Lightning Legend: Daigo no Daibouken', '1996', 'Action', 'VAP', '1', 'Action adventure', '3D fighting game with anime-style characters and magic.', 'Win the tournament to save the world from a supernatural threat.', 'A vibrant and fast-paced 3D fighter with impressive effects.', 'Lightning Legend features a diverse cast and fluid combat. Experience the intensity of this Japanese-exclusive brawler with a deep story mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lilo-&-stitch:-trouble-in-paradise', 'Playstation', 'Lilo & Stitch: Trouble in Paradise', '2002', 'Platformer', 'Climax Studios', '1', 'Platform adventure', '3D action-platformer based on the Disney animated film.', 'Help Lilo and Stitch navigate the island and defeat Gantu''s forces.', 'A colorful and family-friendly adventure with two playstyles.', 'Lilo & Stitch: Trouble in Paradise features exploration and combat. Switch between the heroes to solve puzzles and clear levels in Hawaii.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('loaded-usa', 'Playstation', 'Loaded (USA)', '1996', 'Shooter', 'Gremlin Interactive', '2', 'Top-down shooter', 'Top-down run-and-gun shooter with explosive violence.', 'Fight through a high-security prison to take revenge on your captors.', 'A chaotic, gore-filled shooter with a dark comic book style.', 'Loaded is an intense, high-energy blast of 32-bit carnage. Choose from six deranged characters and leave a trail of destruction in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes---sheep-raider', 'Playstation', 'Looney Tunes - Sheep Raider', '1999', 'Platformer', 'Saffire', '1', 'Stealth platformer', 'Stealth-based puzzle adventure starring Ralph Wolf and Sam Sheepdog.', 'Steal the sheep from under Sam''s nose using ACME gadgets.', 'A brilliant and funny game that captures the spirit of the cartoons.', 'Sheep Raider (known as Sheep, Dog ''n'' Wolf in EU) is a clever logic-based platformer. Use strategy and iconic gadgets to outsmart your rival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('looney-tunes-racing-usa-enfres', 'Playstation', 'Looney Tunes Racing (USA) (En,Fr,Es)', '2000', 'Racing', 'Infogrames', '4', 'Arcade racing', 'Kart racing featuring the iconic Looney Tunes cast.', 'Win races and use ACME traps to outpace your cartoon rivals.', 'A wacky and high-speed racer with vibrant 3D tracks.', 'Looney Tunes Racing delivers pure cartoon mayhem. Master the unique character stats and navigate diverse movie-inspired environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lost-world-the---jurassic-park-usa', 'Playstation', 'Lost World, The - Jurassic Park (USA)', '1997', 'Action', 'DreamWorks Interactive', '1', 'Action adventure', 'Third-person action-adventure with multiple playable perspectives.', 'Survive the dinosaur-infested island as both humans and predators.', 'A cinematic tie-in with impressive graphics and atmosphere.', 'The Lost World: Jurassic Park features a groundbreaking system where you play as a Compy, Raptor, T-Rex, and humans across Isla Sorna.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lsd-dream-emulator', 'Playstation', 'LSD Dream Emulator', '1998', 'Adventure', 'Asmik Ace Entertainment', '1', 'Experimental adventure', 'Surreal and experimental first-person "dream" simulator.', 'Explore a procedural dreamscape to experience bizarre visions.', 'A legendary, abstract title with no formal goals or combat.', 'LSD Dream Emulator is a unique psychological experience. Simply touch objects and walk through ever-shifting environments in this cult masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lucky-luke---western-fever-europe-enfrdeesitnl', 'Playstation', 'Lucky Luke - Western Fever (Europe) (En,Fr,De,Es,It,Nl)', '2001', 'Platformer', 'Infogrames', '1', 'Action platformer', '3D rail-shooter and action game with a Wild West theme.', 'Help Lucky Luke arrest the Daltons and restore peace to the prairie.', 'A fast-paced and humorous western based on the iconic comic book.', 'Lucky Luke - Western Fever features diverse mini-games and shooting galleries. Experience the charm of the "lonesome cowboy" in this vibrant 3D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('lucky-luke-usa', 'Playstation', 'Lucky Luke (USA)', '1997', 'Platformer', 'Infogrames', '1', 'Action platformer', '2D side-scrolling platformer with puzzles and shooting.', 'Chase the Daltons across various Western-themed levels.', 'A classic and colorful platformer that stays true to the comic art.', 'Lucky Luke on PS1 delivers authentic western action. Use your quick-draw skills and outsmart the outlaws in this challenging 2D journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('m&ms---shell-shocked', 'Playstation', 'M&M''s - Shell Shocked', '2000', 'Action', 'Runecraft', '1', 'Action adventure', '3D action-adventure featuring the iconic candy mascots.', 'Retrieve the missing candy shells across a variety of 3D levels.', 'A fun and family-friendly platformer starring Red and Yellow.', 'M&M''s - Shell Shocked features high-energy gameplay and humor. Master different character abilities to navigate hazards in this sweet 32-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('magical-tetris-challenge-europe', 'Playstation', 'Magical Tetris Challenge (Europe)', '1999', 'Puzzle', 'Capcom', '2', 'Puzzle game', 'Competitive puzzle game with a Disney and Tetris theme.', 'Defeat rivals in Tetris matches to win the magical tournament.', 'A unique collaboration between Capcom, Disney, and Tetris.', 'Magical Tetris Challenge features Mickey, Minnie, and Pete. Master "Pentomino" pieces and special attacks in this colorful and addictive puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('martian-gothic---unification-usa', 'Playstation', 'Martian Gothic - Unification (USA)', '2000', 'Horror', 'Creature Labs', '1', 'Survival horror', 'Survival horror with a focus on puzzles and item management.', 'Investigate a silent Martian base and solve the mystery of Vita-01.', 'A difficult and atmospheric sci-fi horror game with three protagonists.', 'Martian Gothic - Unification offers a "Resident Evil" style experience on Mars. Coordinate three characters to survive cosmic terrors and intricate puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-heroes', 'Playstation', 'Marvel Super Heroes', '1996', 'Fighting', 'Capcom', '2', '2D fighting', '2D fighting game featuring iconic Marvel characters.', 'Defeat Dr. Doom and Thanos to collect the Infinity Gems.', 'A foundational Marvel fighter with massive sprites and cinematic moves.', 'Marvel Super Heroes brings the Infinity Gauntlet saga to life. Use Gems to power up your abilities in this classic high-energy brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-super-heroes-vs-street-fighter', 'Playstation', 'Marvel Super Heroes vs Street Fighter', '1997', 'Fighting', 'Capcom', '2', '2D fighting', '2D crossover fighting game with team-based combat.', 'Win the tag-team tournament against Marvel and Capcom rivals.', 'A fast-paced and flashy fighter featuring the "Variable Assist" system.', 'Marvel Super Heroes vs Street Fighter offers explosive combos. Pit Ryu against Spider-Man in this landmark 2D crossover hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-vs-capcom---clash-of-super-heroes---ex-edition-japan', 'Playstation', 'Marvel vs. Capcom - Clash of Super Heroes - EX Edition (Japan)', '1998', 'Fighting', 'Capcom', '2', '2D fighting', '2D tag-team fighting game with massive character rosters.', 'Stop the cosmic threat Onslaught in epic 2-on-2 battles.', 'The definitive Japanese version featuring the exclusive EX Mode.', 'Marvel vs. Capcom (EX Edition) delivers the ultimate crossover experience. Master dual-team attacks and secret strikers in this high-octane classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('marvel-vs-capcom:-clash-of-super-heroes', 'Playstation', 'Marvel vs. Capcom: Clash of Super Heroes', '1998', 'Fighting', 'Capcom', '2', '2D fighting', '2D tag-team fighting game with massive character rosters.', 'Stop the cosmic threat Onslaught in epic 2-on-2 battles.', 'The high-energy Western release of the legendary arcade crossover.', 'Marvel vs. Capcom: Clash of Super Heroes features fluid animation and chaotic combat. Command heroes from both universes to save reality.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mary-kate-and-ashley---winners-circle', 'Playstation', 'Mary-Kate and Ashley - Winners Circle', '2001', 'Sports', 'NDS', '4', 'Party sports', 'Horse racing and management simulation for younger players.', 'Train your horse and win various equestrian competitions.', 'A gentle and creative simulation starring the famous twins.', 'Mary-Kate and Ashley - Winners Circle is perfect for horse lovers. Customize your steed and master the courses in this accessible family game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mat-hoffmans-pro-bmx-usa', 'Playstation', 'Mat Hoffman''s Pro BMX (USA)', '2001', 'Sports', 'Z-Axis', '2', 'Extreme sports', 'Professional freestyle BMX simulation with tricks and stunts.', 'Score high points and complete objectives across urban parks.', 'A high-flying bike game from the creators of Tony Hawk''s Pro Skater.', 'Mat Hoffman''s Pro BMX brings the extreme sports thrill to PS1. Pull off massive airs and technical grinds in this addictive and fast-paced sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('medal-of-honor---underground', 'Playstation', 'Medal of Honor - Underground', '2000', 'Shooter', 'DreamWorks Interactive', '1', 'First-person shooter', 'First-person shooter set in World War II with stealth elements.', 'Infiltrate Nazi-occupied Europe as a member of the French Resistance.', 'A cinematic and atmospheric sequel featuring a female lead.', 'Medal of Honor - Underground expands the series with improved AI and missions. Master covert operations and sabotage in this historical shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('medal-of-honor-usa', 'Playstation', 'Medal of Honor (USA)', '1999', 'Shooter', 'DreamWorks Interactive', '1', 'First-person shooter', 'First-person shooter set in World War II with a cinematic story.', 'Complete various military objectives behind enemy lines.', 'The legendary game that defined the cinematic WWII shooter genre.', 'Medal of Honor (USA) delivers intense atmosphere and orchestral music. Fight through iconic European battlefields in this immersive military classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('medievil', 'Playstation', 'MediEvil', '1998', 'Action', 'SCE Cambridge Studio', '1', 'Action adventure', '3D action-adventure with hack-and-slash combat and puzzles.', 'Defeat the sorcerer Zarok and reclaim your honor as a knight.', 'A spooky, funny, and atmospheric adventure starring Sir Dan Fortesque.', 'MediEvil is a PlayStation classic. Use a variety of weapons to survive the graveyard and save the kingdom of Gallowmere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('medievil-2', 'Playstation', 'MediEvil 2', '2000', 'Action', 'SCE Cambridge Studio', '1', 'Action adventure', '3D action-adventure set in Victorian London with gothic themes.', 'Stop Lord Palethorn and his army of the undead in the 19th century.', 'An expanded sequel with more weapons and complex levels.', 'MediEvil 2 brings Sir Dan back to life in a new era. Explore steampunk-inspired London and fight cosmic horrors in this stylish sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-8', 'Playstation', 'Mega Man 8', '1996', 'Platformer', 'Capcom', '1', '2D platformer', '2D side-scrolling action platformer with beautiful sprite art.', 'Defeat Dr. Wily and his new group of powerful Robot Masters.', 'The only mainline Mega Man entry originally developed for 32-bit.', 'Mega Man 8 features vibrant animation and challenging bosses. Master the Mega Buster and find hidden upgrades in this colorful 2D hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-legends', 'Playstation', 'Mega Man Legends', '1997', 'Action', 'Capcom', '1', 'Action RPG', '3D action-adventure with RPG elements and exploration.', 'Explore the ruins of Kattelox Island to find legendary treasure.', 'A charming and revolutionary departure for the Mega Man series.', 'Mega Man Legends features a fully 3D world and a deep story. Help Mega Man Volnutt uncover the secrets of the past in this beloved adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-legends-2', 'Playstation', 'Mega Man Legends 2', '2000', 'Action', 'Capcom', '1', 'Action RPG', '3D action-adventure with improved combat and larger worlds.', 'Search for the Mother Lode and uncover Mega Man''s origins.', 'An epic and polished sequel with a refined lock-on system.', 'Mega Man Legends 2 delivers more exploration and emotional stakes. Fight massive bosses and explore diverse islands in this definitive 3D entry.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x3', 'Playstation', 'Mega Man X3', '1996', 'Platformer', 'Capcom', '1', '2D platformer', '2D side-scrolling action platformer with the Ride Armor system.', 'Stop the Maverick uprising led by Dr. Doppler.', 'The final entry of the X series on 16-bit, ported to PlayStation.', 'Mega Man X3 features the debut of Zero as a playable character. Upgrade X with powerful chips to defeat the Maverick threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x4', 'Playstation', 'Mega Man X4', '1997', 'Platformer', 'Capcom', '1', '2D platformer', '2D side-scrolling action with high-quality anime cutscenes.', 'Stop the Maverick Hunters from being framed by Sigma.', 'Widely considered the best entry in the Mega Man X series.', 'Mega Man X4 offers two distinct campaigns for X and Zero. Experience fast-paced combat and a tragic story in this 32-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x5', 'Playstation', 'Mega Man X5', '2000', 'Platformer', 'Capcom', '1', '2D platformer', '2D side-scrolling action with a focus on the "Eurasia" crisis.', 'Prevent the space colony from crashing into Earth.', 'A tactical entry featuring multiple armors and the "Parts" system.', 'Mega Man X5 delivers a high-stakes narrative with multiple endings. Master the Falcon and Gaea armors to stop Sigma''s latest plot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x5-improvement-project-addendum', 'Playstation', 'Mega Man X5 Improvement Project Addendum', '2000', 'Platformer', 'Capcom', '1', '2D platformer', 'Enhanced version of Mega Man X5 with balance and QoL fixes.', 'Save the Earth with improved gameplay and less interruption.', 'A fan-made refinement that fixes many of the original''s flaws.', 'Mega Man X5 Improvement Project Addendum offers the definitive way to play. Enjoy faster dialogue and better part-unlocks in this polished hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x5-ns-edition-v176', 'Playstation', 'Mega Man X5 N''s Edition (v1.7.6)', '2000', 'Platformer', 'Capcom', '1', '2D platformer', 'Complete overhaul of Mega Man X5 with new features.', 'Experience X5 with a focus on modern difficulty and balance.', 'A major modification that reworks mechanics and enemy behavior.', 'Mega Man X5 N''s Edition (v1.7.6) provides a fresh challenge for veterans. Featuring massive gameplay tweaks and a more fluid experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x6', 'Playstation', 'Mega Man X6', '2001', 'Platformer', 'Capcom', '1', '2D platformer', '2D side-scrolling action with the "Nightmare" system.', 'Investigate the Maverick outbreaks and the mystery of Gate.', 'A challenging and controversial entry known for its high difficulty.', 'Mega Man X6 features the powerful Blade and Shadow armors. Rescue reploids and navigate hazardous stages in this intense 2D brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man-x6-tweaks', 'Playstation', 'Mega Man X6 Tweaks', '2001', 'Platformer', 'Capcom', '1', '2D platformer', 'Fan-patched version of X6 with significant balance improvements.', 'Experience X6 without the frustrating difficulty spikes.', 'A essential modification that fixes level design and mechanic issues.', 'Mega Man X6 Tweaks transforms a flawed classic into a fair and fun experience. Perfect for fans who want to enjoy the story without the "Nightmare."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mega-man:-battle-&-chase', 'Playstation', 'Mega Man: Battle & Chase', '1997', 'Racing', 'Capcom', '2', 'Arcade racing', 'Combat racing game featuring Mega Man characters.', 'Win the Grand Prix and stop Dr. Wily''s racing machines.', 'A unique and fun spin-off combining racing with shooting.', 'Mega Man: Battle & Chase lets you customize your car with parts from defeated rivals. Master the tracks and use special weapons to finish first.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('megatudo-2096', 'Playstation', 'Megatudo 2096', '1998', 'Sports', 'Konami', '2', 'Arcade soccer', '3D first-person shooter/mecha combat simulator.', 'Pilot a high-tech mech to complete dangerous urban missions.', 'A gritty and technical mecha-action game from Japan.', 'Megatudo 2096 features intense 32-bit robot combat. Customize your walker and blast through enemy forces in this futuristic industrial brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('meitantei-conan-japan', 'Playstation', 'Meitantei Conan (Japan)', '1998', 'Adventure', 'Bandai', '1', 'Detective adventure', 'Mystery adventure game based on the famous detective manga.', 'Solve complex crimes and find clues as the brilliant Conan Edogawa.', 'A faithful adaptation featuring puzzles and logic-based deduction.', 'Meitantei Conan (Detective Conan) brings the anime''s suspense to PS1. Interact with characters and crack the case in this narrative-driven quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-gear-solid---special-missions-europe', 'Playstation', 'Metal Gear Solid - Special Missions (Europe)', '1999', 'Action', 'Konami', '1', 'Stealth action', 'Stealth-action expansion with 300 tactical VR missions.', 'Master the art of infiltration, weaponry, and advanced tactics.', 'The European version of the massive MGS content expansion.', 'Metal Gear Solid - Special Missions is a test of skill for any fan. Experience quirky and challenging scenarios that push the engine to its limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-gear-solid---vr-missions-usa', 'Playstation', 'Metal Gear Solid - VR Missions (USA)', '1999', 'Action', 'Konami', '1', 'Stealth action', 'Stealth-action expansion with 300 tactical VR missions.', 'Master the art of infiltration, weaponry, and advanced tactics.', 'The North American release of the definitive stealth training pack.', 'Metal Gear Solid - VR Missions offers hours of tactical gameplay. Includes puzzles, combat trials, and the chance to play as the Cyborg Ninja.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-gear-solid-usa', 'Playstation', 'Metal Gear Solid (USA)', '1998', 'Action', 'Konami', '1', 'Stealth action', 'Cinematic stealth-action adventure with a deep political story.', 'Infiltrate Shadow Moses and stop the terrorist group Foxhound.', 'Widely regarded as one of the greatest video games of all time.', 'Metal Gear Solid redefined the genre with its "Tactical Espionage Action." Experience an unforgettable story of clones, betrayal, and nuclear threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-slug---super-vehicle-001-japan-asia', 'Playstation', 'Metal Slug - Super Vehicle-001 (Japan, Asia)', '1996', 'Shooter', 'Nazca Corporation', '2', 'Run and gun', '2D side-scrolling run-and-gun with massive destruction.', 'Fight through the Peregrine Falcon squad to defeat General Morden.', 'An incredible port of the legendary arcade action masterpiece.', 'Metal Slug is the pinnacle of 2D pixel art and chaotic shooting. Rescue prisoners and pilot the Super Vehicle-001 in this non-stop brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('metal-slug-x-usa', 'Playstation', 'Metal Slug X (USA)', '1999', 'Shooter', 'SNK', '2', 'Run and gun', 'Enhanced 2D run-and-gun with new weapons and enemies.', 'Stop the alien invasion and Morden''s forces in a global conflict.', 'A polished "remix" of Metal Slug 2 with better performance.', 'Metal Slug X offers even more explosive action and absurd humor. Face off against martians and tanks in this definitive 2D arcade shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-wild-adventure', 'Playstation', 'Mickey''s Wild Adventure', '1997', 'Platformer', 'Traveller''s Tales', '1', '2D platformer', 'Cinematic 2D platformer covering Mickey Mouse''s film history.', 'Travel through classic cartoons from Steamboat Willie to The Prince and the Pauper.', 'A visually stunning and challenging tribute to Disney''s mascot.', 'Mickey''s Wild Adventure features incredible animation that mimics the films. Relive the history of Mickey in this difficult and beautiful platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miracle-space-race', 'Playstation', 'Miracle Space Race', '2001', 'Racing', 'Genki', '2', 'Arcade racing', 'Arcade-style racing with a futuristic sci-fi theme.', 'Win high-speed races across alien planets and cosmic tracks.', 'A fast-paced and colorful racer for fans of sci-fi driving.', 'Miracle Space Race offers accessible fun with a variety of ships and tracks. Master the boosts and outrun the competition in this intergalactic race.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('misadventures-of-tron-bonne-the', 'Playstation', 'Misadventures of Tron Bonne, The', '1999', 'Action', 'Capcom', '1', 'Action adventure', 'Action-adventure with strategy and puzzle-solving elements.', 'Lead the Servbots to pull off heists and pay off a massive debt.', 'A charming spin-off of the Mega Man Legends series.', 'The Misadventures of Tron Bonne puts you in control of the brilliant anti-heroine. Manage your Servbots and engage in diverse missions in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('misadventures-of-tron-bonne-the', 'Playstation', 'Misadventures of Tron Bonne, The', '1999', 'Action', 'Capcom', '1', 'Action adventure', 'Action-adventure with strategy and puzzle-solving elements.', 'Lead the Servbots to pull off heists and pay off a massive debt.', 'A charming spin-off of the Mega Man Legends series.', 'The Misadventures of Tron Bonne puts you in control of the brilliant anti-heroine. Manage your Servbots and engage in diverse missions in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miss-spiders-tea-party', 'Playstation', 'Miss Spider''s Tea Party', '1996', 'Educational', 'Intraware', '1', 'Educational adventure', 'Collection of mini-games and puzzles for young children.', 'Help Miss Spider gather her friends for a special tea party.', 'A colorful and gentle educational game for early learners.', 'Miss Spider''s Tea Party features simple logic puzzles and interactive stories. Perfect for young fans of the book series looking for safe, fun gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mission---impossible-usa', 'Playstation', 'Mission - Impossible (USA)', '1998', 'Action', 'Infogrames', '1', 'Action adventure', 'Third-person stealth-action based on the 1996 film.', 'Complete high-stakes espionage missions to clear Ethan Hunt''s name.', 'A tactical action game with gadgets and infiltration.', 'Mission - Impossible brings the tension of the movie to PS1. Use masks, gas, and high-tech tools to navigate dangerous levels across the globe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mobile-suit-gundam---chars-counterattack', 'Playstation', 'Mobile Suit Gundam - Char''s Counterattack', '1999', 'Action', 'Bandai', '2', 'Action combat', '3D mecha-fighting game based on the iconic anime film.', 'Relive the final duel between Amuro Ray and Char Aznable.', 'A high-energy fighter featuring massive Mobile Suits.', 'Mobile Suit Gundam - Char''s Counterattack offers cinematic robot combat. Master the Nu Gundam and Sazabi in this faithful anime adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mobile-suit-gundam:-version-20', 'Playstation', 'Mobile Suit Gundam: Version 2.0', '1999', 'Action', 'Bandai', '2', 'Action combat', '3D first-person mecha combat simulation.', 'Pilot the RX-78-2 Gundam and complete missions from the One Year War.', 'A tactical and realistic take on the Gundam universe.', 'Mobile Suit Gundam: Version 2.0 features improved physics and graphics. Experience the power of a Mobile Suit in this detailed combat simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monaco-grand-prix', 'Playstation', 'Monaco Grand Prix', '2000', 'Racing', 'UBI Soft', '2', 'Formula racing', 'Formula 1 racing simulation with professional handling.', 'Win the world championship across various international tracks.', 'A technical and realistic open-wheel racing game.', 'Monaco Grand Prix delivers high-speed F1 excitement. Master the physics of the track and outrun the pack in this polished 32-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-rancher-2', 'Playstation', 'Monster Rancher 2', '1999', 'RPG', 'Tecmo', '1', 'Monster training RPG', 'Monster-raising simulation with turn-based combat.', 'Breed, train, and battle monsters to become the top rancher.', 'A deep and addictive sim where CDs generate unique creatures.', 'Monster Rancher 2 is the peak of the series. Use your music collection to unlock hundreds of monsters and lead them to victory in tournaments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-rancher-battle-card---episode-ii', 'Playstation', 'Monster Rancher Battle Card - Episode II', '2000', 'Card', 'Game Studio', '2', 'Card battle game', 'Tactical card-battle game based on the Monster Rancher world.', 'Use strategic card plays to defeat rival monster trainers.', 'A deep and competitive CCG (Collectible Card Game) experience.', 'Monster Rancher Battle Card - Episode II offers strategic depth for fans. Build the ultimate deck and master creature synergies in this turn-based hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-rancher-hop-a-bout', 'Playstation', 'Monster Rancher Hop-A-Bout', '2000', 'Action', 'Tecmo', '2', 'Party action', '3D puzzle-platformer featuring Monster Rancher creatures.', 'Navigate treacherous obstacle courses to reach the finish line.', 'A fun and challenging spin-off focused on timing and jumps.', 'Monster Rancher Hop-A-Bout features your favorite monsters in a race against the clock. Master the jumps to survive this vibrant 3D obstacle course.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moon:-remix-rpg-adventure-english', 'Playstation', 'Moon: Remix RPG Adventure (English)', '1997', 'RPG', 'Love-de-Lic', '1', 'Experimental RPG', 'Narrative-driven RPG focused on helping souls and non-violence.', 'Restore "Love" to the world and fix the damage caused by a "Hero."', 'An English-translated cult masterpiece that parodies RPG tropes.', 'Moon: Remix RPG Adventure is a unique "Anti-RPG." Instead of killing monsters, you save their souls in this beautiful and surreal narrative journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mort-the-chicken-usa', 'Playstation', 'Mort the Chicken (USA)', '2001', 'Platformer', 'And Now', '1', '3D platformer', '3D platformer featuring a heroic farm chicken.', 'Rescue your kidnapped chicks from a mysterious intergalactic threat.', 'A quirky and lighthearted adventure for all ages.', 'Mort the Chicken brings poultry power to the PS1. Use Mort''s unique moves to navigate vibrant levels and save your family in this fun 3D game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat---special-forces', 'Playstation', 'Mortal Kombat - Special Forces', '2000', 'Action', 'Midway', '1', 'Action adventure', 'Third-person action brawler starring Jax.', 'Track down Kano and the Black Dragon syndicate.', 'A gritty action spin-off of the Mortal Kombat universe.', 'Mortal Kombat - Special Forces features heavy combat and exploration. Use Jax''s strength and gadgets to clean up the streets in this urban brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-2', 'Playstation', 'Mortal Kombat 2', '1993', 'Fighting', 'Midway', '2', '2D fighting', '2D fighting game with digitized sprites and "Fatalities."', 'Defeat the emperor Shao Kahn in the Outworld tournament.', 'A legendary and brutal sequel that defined the fighting genre.', 'Mortal Kombat 2 offers a larger roster and more "Babalities" and "Friendships." Master the blood-soaked combat of this arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3', 'Playstation', 'Mortal Kombat 3', '1995', 'Fighting', 'Midway', '2', '2D fighting', '2D fighting game with a "Run" button and "Animalities."', 'Stop Shao Kahn''s invasion of Earthrealm.', 'A high-speed entry featuring robotic ninjas and massive combos.', 'Mortal Kombat 3 introduces the "Kombat Kodes" and interactive stages. Experience the ultimate struggle for Earth in this explosive brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-4', 'Playstation', 'Mortal Kombat 4', '1998', 'Fighting', 'Midway', '2', '3D fighting', '3D fighting game featuring specialized weapon combat.', 'Defeat the fallen Elder God Shinnok and his dark forces.', 'The first entry in the series to transition into full 3D.', 'Mortal Kombat 4 delivers bone-crunching 3D action. Use environmental objects and signature weapons to finish your opponents in style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-mythologies:-sub-zero', 'Playstation', 'Mortal Kombat Mythologies: Sub-Zero', '1997', 'Action', 'Midway', '1', 'Action adventure', '2D side-scrolling action-adventure starring Sub-Zero.', 'Recover an ancient amulet and stop Quan Chi''s dark ritual.', 'A challenging platformer that expands the MK lore.', 'Mortal Kombat Mythologies: Sub-Zero combines fighting mechanics with exploration. Uncover the origin story of the legendary Lin Kuei ninja.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-trilogy', 'Playstation', 'Mortal Kombat Trilogy', '1996', 'Fighting', 'Midway', '2', 'Fighting compilation', 'Definitive 2D fighting compilation of the first three games.', 'Choose from over 30 characters and win the ultimate tournament.', 'A massive "Best Of" package for the 2D era of Mortal Kombat.', 'Mortal Kombat Trilogy features every character and stage from the original hits. Execute classic Fatalities in this comprehensive fighting collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moses---prince-of-egypt-europe-enfrdenl', 'Playstation', 'Moses - Prince of Egypt (Europe) (En,Fr,De,Nl)', '1999', 'Adventure', 'Nevosoft', '1', 'Biblical adventure', '3D action-adventure based on the DreamWorks animated film.', 'Lead Moses to free his people and reach the Promised Land.', 'A cinematic journey with puzzles and platforming segments.', 'Moses - Prince of Egypt captures the epic scale of the movie. Solve environmental puzzles and witness the miracles of the Exodus.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motocross-mania-2', 'Playstation', 'Motocross Mania 2', '2000', 'Racing', 'Deibus Studios', '2', 'Motocross racing', 'Fast-paced arcade motocross racing with stunts.', 'Win races across diverse tracks and pull off insane air tricks.', 'A high-energy budget racer with a focus on speed.', 'Motocross Mania 2 offers accessible dirt bike fun. Master the jumps and outpace your rivals in this fast and flashy extreme sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('motorhead', 'Playstation', 'Motorhead', '1998', 'Racing', 'Digital Illusions CE', '2', 'Arcade racing', 'High-speed futuristic racing with a focus on 60fps performance.', 'Dominate the tracks in powerful, high-tech racing machines.', 'A stylish and incredibly fast racer with a techno vibe.', 'Motorhead delivers pure speed on the PS1. Experience smooth frame rates and intense competition in this visually impressive arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-driller', 'Playstation', 'Mr. Driller', '1999', 'Puzzle', 'Namco', '2', 'Action puzzle', '2D action-puzzle game involving drilling through colored blocks.', 'Drill as deep as possible while managing your oxygen supply.', 'An addictive and colorful arcade hit with a simple premise.', 'Mr. Driller is a test of speed and planning. Avoid falling blocks and dig deep into the earth in this vibrant and rhythmic puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mr-driller-japan', 'Playstation', 'Mr. Driller (Japan)', '1999', 'Puzzle', 'Namco', '2', 'Action puzzle', '2D action-puzzle game involving drilling through colored blocks.', 'Drill as deep as possible while managing your oxygen supply.', 'The original Japanese release of the iconic Namco puzzler.', 'Mr. Driller (Japan) offers the pure arcade experience. Master the drilling mechanics and climb the high-score leaderboards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-maze-madness-usa', 'Playstation', 'Ms. Pac-Man Maze Madness (USA)', '2000', 'Action', 'Mass Media', '2', 'Action maze', '3D maze-adventure with classic Pac-Man gameplay elements.', 'Navigate complex mazes to stop the ghostly Professor Pac.', 'A creative 3D evolution of the Pac-Man formula.', 'Ms. Pac-Man Maze Madness features puzzles, collectibles, and classic dodging. Explore diverse worlds in this charming and polished 3D quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mtv-celebrity-deathmatch', 'Playstation', 'MTV Celebrity Deathmatch', '2001', 'Fighting', 'Yuke''s', '2', '3D fighting', 'Arena-based 3D fighting game based on the MTV show.', 'Battle celebrities in brutal, over-the-top deathmatches.', 'A comedic and violent brawler featuring claymation-style visuals.', 'MTV Celebrity Deathmatch brings the TV carnage home. Choose your favorite star and use absurd special moves to win the ultimate popularity contest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mtv-music-generator', 'Playstation', 'MTV Music Generator', '1999', 'Music', 'Jester Interactive', '1', 'Music creation', 'Music creation software for the PlayStation.', 'Create your own tracks using a library of loops and samples.', 'A powerful and intuitive tool for aspiring digital musicians.', 'MTV Music Generator (Music 2000) is a professional-grade creation suite. Compose complex songs and share them with friends in this creative gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mtv-sports---skateboarding-featuring-andy-macdonald-usa', 'Playstation', 'MTV Sports - Skateboarding featuring Andy Macdonald (USA)', '2000', 'Sports', 'Darkblack', '2', 'Skateboarding', 'Professional skateboarding simulation with a focus on style.', 'Complete trick-based objectives and win skate competitions.', 'A solid extreme sports title featuring top pro Andy Macdonald.', 'MTV Sports - Skateboarding delivers realistic physics and urban parks. Master technical grinds and huge airs in this atmospheric skate sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mtv-sports---snowboarding-usa', 'Playstation', 'MTV Sports - Snowboarding (USA)', '1998', 'Sports', 'UBI Soft', '2', 'Snowboarding', 'High-speed snowboarding simulation with tricks and racing.', 'Conquer the mountain by winning races and scoring trick points.', 'A high-energy snow sports game with a diverse soundtrack.', 'MTV Sports - Snowboarding offers multiple peaks and riders. Experience the rush of the slopes and master the halfpipe in this extreme sports hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mummy-the-usa', 'Playstation', 'Mummy, The (USA)', '2000', 'Action', 'Rebellion Developments', '1', 'Action adventure', '3D action-adventure based on the 1999 blockbuster film.', 'Defeat the high priest Imhotep and escape the cursed city.', 'A cinematic adventure with puzzles, combat, and exploration.', 'The Mummy brings the thrill of the movie to life. Explore Hamunaptra, solve ancient mysteries, and survive the undead in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muppet-monster-adventure', 'Playstation', 'Muppet Monster Adventure', '2000', 'Platformer', 'Traveller''s Tales', '1', '3D platformer', '3D platformer starring a heroic Muppet monster.', 'Rescue your friends and defeat Baron Petri von Hellsing.', 'A charming and spooky adventure in the vein of Spyro.', 'Muppet Monster Adventure features diverse Muppet forms and abilities. Explore gothic-themed levels in this high-quality and funny platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('muppet-racemania-usa', 'Playstation', 'Muppet RaceMania (USA)', '2000', 'Racing', 'Traveller''s Tales', '2', 'Arcade racing', 'Kart racing featuring the legendary Muppet cast.', 'Win races and use wacky power-ups to outpace your rivals.', 'A fun and chaotic racer with tracks based on Muppet history.', 'Muppet RaceMania features 25 playable Muppets and iconic locations. Experience high-speed fun and Muppet humor in this vibrant kart racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('music---music-creation-for-the-playstation', 'Playstation', 'Music - Music Creation For The PlayStation', '1997', 'Music', 'Jester Interactive', '1', 'Music creation', 'Music creation and sampling software for the PlayStation.', 'Arrange samples and beats to create original musical compositions.', 'An accessible tool for making electronic music on your console.', 'Music - Music Creation For The PlayStation is the foundation of the genre. Experiment with sounds and loops to craft your own unique tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-encore', 'Playstation', 'Namco Museum Encore', '1997', 'Compilation', 'Namco', '2', 'Arcade compilation', 'Compilation of classic Namco arcade titles from the 80s.', 'Relive the arcade glory days with high scores and classic play.', 'A special Japanese edition featuring rare hits like Rolling Thunder.', 'Namco Museum Encore brings even more arcade legends home. Enjoy pixel-perfect ports of classics in one nostalgic package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-encore-japan', 'Playstation', 'Namco Museum Encore (Japan)', '1997', 'Compilation', 'Namco', '2', 'Arcade compilation', 'Compilation of classic Namco arcade titles from the 80s.', 'Relive the arcade glory days with high scores and classic play.', 'The original Japanese release of the "Encore" collection.', 'Namco Museum Encore (Japan) features a curated selection of hits. Master the classics and enjoy the virtual museum experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-vol-1', 'Playstation', 'Namco Museum Vol. 1', '1995', 'Compilation', 'Namco', '2', 'Arcade compilation', 'Compilation of classic Namco arcade titles including Pac-Man.', 'Explore the virtual museum and achieve high scores in the classics.', 'The foundational collection of Namco''s greatest arcade hits.', 'Namco Museum Vol. 1 features Pac-Man, Galaga, and Pole Position. Experience the history of gaming with authentic ports and 3D museum content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-vol-2', 'Playstation', 'Namco Museum Vol. 2', '1996', 'Compilation', 'Namco', '2', 'Arcade compilation', 'Collection of classic Namco arcade titles including Xevious.', 'Explore the 3D museum and achieve high scores in the classics.', 'The second volume of Namco''s legendary arcade compilation.', 'Namco Museum Vol. 2 features hits like Mappy and Gaplus. Relive the golden age of gaming with authentic arcade ports and bonus museum content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-vol-3', 'Playstation', 'Namco Museum Vol. 3', '1996', 'Compilation', 'Namco', '2', 'Arcade compilation', 'Collection of classic Namco arcade titles including Dig Dug.', 'Explore the 3D museum and achieve high scores in the classics.', 'The third volume featuring foundational 80s arcade hits.', 'Namco Museum Vol. 3 includes Galaxian, Ms. Pac-Man, and Pole Position II. A must-have for retro fans seeking pixel-perfect arcade experiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-vol-4', 'Playstation', 'Namco Museum Vol. 4', '1996', 'Compilation', 'Namco', '2', 'Arcade compilation', 'Collection of classic Namco arcade titles including Ordyne.', 'Explore the 3D museum and achieve high scores in the classics.', 'The fourth volume focusing on deep-cut arcade treasures.', 'Namco Museum Vol. 4 brings Genji and the Heike Clans and Pac-Land to the PS1. Discover rare gems with authentic controls and history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('namco-museum-vol-5', 'Playstation', 'Namco Museum Vol. 5', '1997', 'Compilation', 'Namco', '2', 'Arcade compilation', 'Collection of classic Namco arcade titles including Metro-Cross.', 'Explore the 3D museum and achieve high scores in the classics.', 'The fifth and final standard volume of the museum series.', 'Namco Museum Vol. 5 features Dragon Spirit and Pac-Mania. Complete your collection with these high-quality 32-bit arcade ports.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('naruto:-shinobi-no-sato-no-jintori-kassen', 'Playstation', 'Naruto: Shinobi no Sato no Jintori Kassen', '2003', 'Strategy', 'Tomy', '2', 'Turn-based strategy', 'Strategic board-game style combat with Naruto characters.', 'Conquer territories and defeat rival ninjas using Jutsu cards.', 'The very first Naruto game ever released, exclusive to Japan.', 'Naruto: Shinobi no Sato no Jintori Kassen features early anime art. Master tactical positioning and ninja abilities in this unique board-battle hybrid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-2000-usa', 'Playstation', 'NASCAR 2000 (USA)', '1999', 'Racing', 'Stormfront Studios', '2', 'NASCAR racing', 'Stock car racing simulation with licensed 2000 season data.', 'Win the Winston Cup and master the high-speed oval tracks.', 'A polished NASCAR entry with improved physics and car damage.', 'NASCAR 2000 brings the thrill of professional stock car racing to life. Race with legends like Jeff Gordon and Dale Earnhardt in this fast-paced sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-2001-usa', 'Playstation', 'NASCAR 2001 (USA)', '2000', 'Racing', 'Stormfront Studios', '2', 'NASCAR racing', 'Stock car racing simulation with 2001 season rosters.', 'Lead your team to victory in the premier racing series.', 'The refined 2001 edition featuring updated cars and tracks.', 'NASCAR 2001 offers authentic handling and realistic pit stops. Experience the intensity of the track with improved AI and TV-style presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-98-usa', 'Playstation', 'NASCAR 98 (USA)', '1997', 'Racing', 'Papyrus Design Group', '2', 'NASCAR simulation', 'High-speed stock car racing with 1998 season licensing.', 'Outrun your rivals and survive the chaos of the oval.', 'The foundational NASCAR title for the original PlayStation.', 'NASCAR 98 features a legendary soundtrack and arcade-style thrills. Master the draft and cross the finish line first in this racing classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-98-collectors-edition-usa', 'Playstation', 'NASCAR 98 Collector''s Edition (USA)', '1997', 'Racing', 'Papyrus Design Group', '2', 'NASCAR simulation', 'Stock car racing simulation with bonus 1998 content.', 'Celebrate the 50th anniversary of NASCAR with special events.', 'A special edition featuring a tribute to the sport''s history.', 'NASCAR 98 Collector''s Edition offers expanded rosters and historical tracks. The definitive way to experience the ''98 racing season on PS1.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-99-usa', 'Playstation', 'NASCAR 99 (USA)', '1998', 'Racing', 'Stormfront Studios', '2', 'NASCAR racing', 'Stock car racing simulation with 1999 season updates.', 'Win championships and master the new drafting mechanics.', 'A technical improvement over the previous year''s entry.', 'NASCAR 99 features better car textures and more responsive controls. Compete against the best drivers in the world across authentic tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-99-legacy-usa', 'Playstation', 'NASCAR 99 Legacy (USA)', '1998', 'Racing', 'Stormfront Studios', '2', 'NASCAR racing', 'Stock car racing simulation focusing on 1999 statistics.', 'Relive the 1999 season with accurate car and driver data.', 'A specialized edition focusing on the legacy of the 1999 season.', 'NASCAR 99 Legacy offers deep statistical tracking and realistic racing. Perfect for fans of the technical side of stock car racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-heat-usa', 'Playstation', 'NASCAR Heat (USA)', '2000', 'Racing', 'Monster Games', '2', 'NASCAR racing', 'Arcade-style stock car racing with a focus on speed.', 'Finish first across a variety of professional racing circuits.', 'A fast and accessible NASCAR game for casual racing fans.', 'NASCAR Heat delivers high-octane thrills with simplified controls. Experience the heat of the competition in this action-packed racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-racing', 'Playstation', 'Nascar Racing', '1996', 'Racing', 'Papyrus Design Group', '2', 'NASCAR simulation', 'Early 3D stock car racing simulation.', 'Master the oval and win the seasonal championship.', 'A focused and realistic take on the beginnings of the NASCAR series.', 'Nascar Racing offers a challenging driving experience. Learn the nuances of stock car handling in this foundational 32-bit simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-racing---season-96-japan', 'Playstation', 'NASCAR Racing - Season 96 (Japan)', '1996', 'Racing', 'Papyrus Design Group', '2', 'NASCAR simulation', 'Stock car racing simulation localized for the Japanese market.', 'Win the 1996 season championship on international tracks.', 'The Japanese edition of the early stock car racing sim.', 'NASCAR Racing - Season 96 features localized menus and authentic car data from the mid-90s racing scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-rumble-usa', 'Playstation', 'NASCAR Rumble (USA)', '2000', 'Racing', 'High Voltage Software', '4', 'Arcade racing', 'Arcade vehicular combat racing with power-ups and speed.', 'Destroy your rivals and win races across diverse 3D environments.', 'A fan-favorite "Mario Kart" style racer with NASCAR cars.', 'NASCAR Rumble features crazy power-ups and secret shortcuts. Blast through the competition in this chaotic and hilarious arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-thunder-2002-usa', 'Playstation', 'NASCAR Thunder 2002 (USA)', '2001', 'Racing', 'Budcat Creations', '2', 'NASCAR racing', 'Stock car racing simulation with 2002 season updates.', 'Dominate the Winston Cup with updated teams and graphics.', 'The first of the "Thunder" series entries for the PS1.', 'NASCAR Thunder 2002 offers refined physics and more immersive career modes. Experience the noise and speed of the professional circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-thunder-2003-usa', 'Playstation', 'NASCAR Thunder 2003 (USA)', '2002', 'Racing', 'Budcat Creations', '2', 'NASCAR racing', 'Stock car racing simulation with 2003 season rosters.', 'Build your racing legacy and win the championship.', 'A late-generation NASCAR title with deep management features.', 'NASCAR Thunder 2003 brings more detail to the car models and tracks. Manage your career and master the draft in this polished simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nascar-thunder-2004-usa', 'Playstation', 'NASCAR Thunder 2004 (USA)', '2003', 'Racing', 'Budcat Creations', '2', 'NASCAR racing', 'Stock car racing simulation with 2004 season data.', 'Win the final championship on the original PlayStation hardware.', 'One of the most polished and content-rich NASCAR games for PS1.', 'NASCAR Thunder 2004 offers the definitive stock car experience. Features updated rosters and the most refined driving model of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-hoopz', 'Playstation', 'NBA Hoopz', '2000', 'Sports', 'Midway', '4', 'Arcade basketball', '3-on-3 street basketball with an arcade style.', 'Outscore your opponents with gravity-defying dunks and tricks.', 'A high-energy basketball game from the creators of NBA Jam.', 'NBA Hoopz features fast-paced action and over-the-top animations. Dominate the court with "On Fire" mechanics in this arcade sports hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-extreme', 'Playstation', 'NBA Jam Extreme', '1996', 'Sports', 'Midway', '4', 'Arcade basketball', '2-on-2 basketball with exaggerated moves and dunks.', 'Score spectacular baskets and humiliate your rivals.', 'An extreme and flashy 3D update to the classic NBA Jam.', 'NBA Jam Extreme features the iconic announcer and insane physics. Leap over the rim and shatter the backboard in this high-octane brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-showtime---nba-on-nbc', 'Playstation', 'NBA Showtime - NBA on NBC', '1999', 'Sports', 'Midway', '4', 'Arcade basketball', 'Arcade-style basketball with 2-on-2 gameplay and 3D graphics.', 'Lead your favorite NBA duo to victory in the tournament.', 'A faithful port of the popular "NBA on NBC" arcade machine.', 'NBA Showtime delivers authentic arcade thrills. Featuring realistic player faces and explosive dunks, it''s the peak of 2-on-2 basketball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-basketball-final-four-97-usa', 'Playstation', 'NCAA Basketball Final Four 97 (USA)', '1997', 'Sports', 'EA Sports', '4', 'College basketball', 'College basketball simulation focusing on the 1997 season.', 'Win the NCAA tournament and reach the Final Four.', 'An early and authentic take on college basketball for PS1.', 'NCAA Basketball Final Four 97 features real college teams and tactics. Experience the atmosphere of the campus courts in this classic sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-final-four-2000-usa', 'Playstation', 'NCAA Final Four 2000 (USA)', '1999', 'Sports', 'EA Sports', '4', 'College basketball', 'College basketball simulation with 2000 season rosters.', 'Lead your university to the national championship.', 'A polished and feature-rich college basketball experience.', 'NCAA Final Four 2000 offers deep team management and realistic gameplay. Master the "March Madness" excitement in this detailed sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-final-four-2001-usa', 'Playstation', 'NCAA Final Four 2001 (USA)', '2000', 'Sports', 'EA Sports', '4', 'College basketball', 'College basketball simulation with 2001 season data.', 'Navigate the brackets and win the national title.', 'The refined 2001 entry with improved AI and animations.', 'NCAA Final Four 2001 brings the passion of college sports home. Features updated teams and a deeper tournament mode for hardcore fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-final-four-99', 'Playstation', 'NCAA Final Four 99', '1998', 'Sports', 'EA Sports', '4', 'College basketball', 'College basketball simulation focusing on the 1999 season.', 'Win the national championship in a realistic tournament setting.', 'A foundational entry for the NCAA basketball series on PS1.', 'NCAA Final Four 99 features authentic college arenas and cheering crowds. Experience the road to the Final Four in this sports classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-football-2000-usa', 'Playstation', 'NCAA Football 2000 (USA)', '1999', 'Sports', 'EA Sports', '4', 'College football', 'American college football simulation with 2000 season data.', 'Win the bowl games and lead your team to national glory.', 'A detailed football sim with deep college rosters and plays.', 'NCAA Football 2000 offers authentic college atmosphere and strategy. Manage your playbook and dominate the field in this sports hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ncaa-football-2001-usa', 'Playstation', 'NCAA Football 2001 (USA)', '2000', 'Sports', 'EA Sports', '4', 'College football', 'American college football simulation with 2001 season data.', 'Conquer the college football world and win the Heisman.', 'The refined 2001 edition of the popular football series.', 'NCAA Football 2001 features improved graphics and more realistic player motion. Experience the pageantry and intensity of the college game.');